window.UNIT_DATA["boom-to-bust"] = {"items":[{"id":"a-001","kind":"person","topics":["people","economy"],"chapter":30,"page":705,"term":"Henry Ford","def":"Auto pioneer who built the giant River Rouge complex near Detroit and championed the moving assembly line.","detail":"He said \"History is bunk\" and paid $5 a day in 1914 to cut turnover.","year":1914,"difficulty":1,"aliases":["Ford"]},{"id":"a-002","kind":"concept","topics":["vocab","economy"],"chapter":30,"page":705,"term":"Model T","def":"Cheap, rugged car first built in 1908 that put ordinary Americans on wheels.","detail":"Nicknamed the Tin Lizzie; a mid-1920s Ford roadster sold for $260.","year":1908,"difficulty":1,"aliases":["Tin Lizzie","Model T Ford"]},{"id":"a-003","kind":"concept","topics":["vocab","economy"],"chapter":30,"page":706,"term":"Assembly line","def":"Production method where semi-skilled workers repeat simple tasks as the product moves past them.","detail":"At its peak speed a finished car rolled off Ford\u0027s line every ten seconds.","year":null,"difficulty":1,"aliases":["Moving assembly line","Fordism"]},{"id":"a-004","kind":"person","topics":["people","economy"],"chapter":30,"page":706,"term":"Frederick W. Taylor","def":"Efficiency expert whose stopwatch-driven scientific management inspired Ford\u0027s factory methods.","detail":"His approach aimed to eliminate wasted motion by workers.","year":null,"difficulty":2,"aliases":["Taylor"]},{"id":"a-005","kind":"concept","topics":["vocab","economy"],"chapter":30,"page":706,"term":"Scientific management","def":"Efficiency system using stopwatch timing to remove wasted motion from factory work.","detail":"Ford borrowed it for his assembly-line production.","year":null,"difficulty":1,"aliases":["Taylorism"],"key":["oct28"]},{"id":"a-006","kind":"concept","topics":["vocab","economy"],"chapter":30,"page":706,"term":"Five-dollar day","def":"Ford\u0027s relatively high wage offered to attract dependable workers and reduce quitting.","detail":"Introduced in 1914 as an alternative to high worker turnover.","year":1914,"difficulty":2,"aliases":["$5 a day"]},{"id":"a-007","kind":"concept","topics":["vocab","culture"],"chapter":30,"page":706,"term":"Modern Times","def":"1936 Charlie Chaplin film that mocked the dehumanizing pace of mass-production factory work.","detail":"It satirized the process known as Fordism.","year":1936,"difficulty":3,"aliases":[]},{"id":"a-008","kind":"concept","topics":["vocab","economy"],"chapter":30,"page":705,"term":"River Rouge","def":"Enormous Ford industrial complex near Detroit that symbolized mass production.","detail":"Detroit effectively served as Ford\u0027s capital.","year":null,"difficulty":3,"aliases":["Rouge plant"]},{"id":"a-009","kind":"concept","topics":["vocab","economy"],"chapter":30,"page":707,"term":"Installment buying","def":"Credit method letting modest earners buy cars and appliances through small periodic payments.","detail":"By the late 1920s Americans owned more cars than bathtubs.","year":null,"difficulty":1,"aliases":["Buying on credit","Installment plan"]},{"id":"a-010","kind":"event","topics":["events","economy"],"chapter":30,"page":705,"term":"23 million cars","def":"By the end of the 1920s Americans owned this many automobiles, more than the rest of the world combined.","detail":"About 8 million passenger vehicles were on the road in 1920.","year":1929,"difficulty":2,"aliases":[]},{"id":"a-011","kind":"concept","topics":["vocab","culture"],"chapter":30,"page":706,"term":"Suburbs","def":"Residential areas spread farther from cities thanks to the automobile, creating a nation of commuters.","detail":"The car reorganized work and family life around highways.","year":null,"difficulty":2,"aliases":["Suburbanization"]},{"id":"a-012","kind":"event","topics":["events"],"chapter":30,"page":707,"term":"Wright brothers\u0027 flight","def":"Two Ohio bicycle repairmen made the first powered airplane flight at Kitty Hawk, North Carolina.","detail":"The flight on December 17 lasted 12 seconds and covered 120 feet.","year":1903,"difficulty":1,"aliases":["Kitty Hawk","Wright brothers"]},{"id":"a-013","kind":"person","topics":["people","culture"],"chapter":30,"page":707,"term":"Charles Lindbergh","def":"Aviator who made the first solo transatlantic flight and became a media-made hero.","detail":"He flew the Spirit of St. Louis from New York to Paris in 33 hours 39 minutes.","year":1927,"difficulty":1,"aliases":["Lindbergh","Lone Eagle"],"key":["oct28"]},{"id":"a-014","kind":"concept","topics":["vocab"],"chapter":30,"page":708,"term":"Spirit of St. Louis","def":"Name of the plane Lindbergh flew from New York to Paris.","detail":"Lindbergh won a $25,000 prize and a ticker-tape parade.","year":1927,"difficulty":2,"aliases":[]},{"id":"a-015","kind":"event","topics":["events"],"chapter":30,"page":708,"term":"Lindbergh kidnapping","def":"1932 crime in which the infant son of the famous aviator was kidnapped and murdered.","detail":"It prompted Congress to pass a federal kidnapping law carrying the death penalty.","year":1932,"difficulty":2,"aliases":[]},{"id":"a-016","kind":"law","topics":["vocab"],"chapter":30,"page":718,"term":"Lindbergh Law","def":"Federal law making certain interstate kidnappings a death-penalty offense.","detail":"Passed after the kidnapping and murder of a famous aviator\u0027s infant son.","year":1932,"difficulty":3,"aliases":[]},{"id":"a-017","kind":"person","topics":["people"],"chapter":30,"page":708,"term":"Guglielmo Marconi","def":"Italian inventor of wireless telegraphy in the 1890s, later used in WWI.","detail":"His invention was the foundation for voice radio.","year":null,"difficulty":3,"aliases":["Marconi"]},{"id":"a-018","kind":"event","topics":["events","culture"],"chapter":30,"page":708,"term":"KDKA broadcast","def":"Pittsburgh station that aired the 1920 presidential election returns on November 2.","detail":"It is a milestone in the start of voice radio.","year":1920,"difficulty":2,"aliases":["KDKA"]},{"id":"a-019","kind":"concept","topics":["vocab","culture"],"chapter":30,"page":708,"term":"NBC","def":"First national radio network, created by RCA in 1926 by joining local stations.","detail":"Its first nationwide broadcast was the 1927 Rose Bowl.","year":1926,"difficulty":2,"aliases":["National Broadcasting Company"]},{"id":"a-020","kind":"law","topics":["vocab"],"chapter":30,"page":709,"term":"Federal Radio Commission","def":"Agency created in 1927 to license broadcasters and assign frequencies on crowded airwaves.","detail":"It was later renamed the FCC; US radio stayed private but regulated.","year":1927,"difficulty":2,"aliases":["FRC","FCC"]},{"id":"a-021","kind":"concept","topics":["vocab","culture"],"chapter":30,"page":709,"term":"Amos \u0027n\u0027 Andy","def":"Popular radio show that millions tuned in to, helping standardize accents and unite the nation.","detail":"It was an example of radio\u0027s power to create shared national culture.","year":null,"difficulty":3,"aliases":[]},{"id":"a-022","kind":"concept","topics":["vocab","culture"],"chapter":30,"page":709,"term":"The Jazz Singer","def":"1927 first feature-length talkie that ended the silent film era.","detail":"Starred Al Jolson in blackface as an immigrant torn between cantor duty and jazz.","year":1927,"difficulty":1,"aliases":["Jazz Singer"]},{"id":"a-023","kind":"person","topics":["people","culture"],"chapter":30,"page":709,"term":"Al Jolson","def":"Immigrant Jewish star of the first talkie who performed in blackface.","detail":"He used blackface to gain acceptance in white American society.","year":1927,"difficulty":2,"aliases":["Jolson"]},{"id":"a-024","kind":"concept","topics":["vocab","culture"],"chapter":30,"page":710,"term":"Birth of a Nation","def":"1915 three-hour D. W. Griffith epic glorifying the Ku Klux Klan and defaming Black Americans.","detail":"Black Americans protested; some white Southerners fired guns at the screen.","year":1915,"difficulty":1,"aliases":[]},{"id":"a-025","kind":"concept","topics":["vocab","culture"],"chapter":30,"page":710,"term":"Nickelodeons","def":"Five-cent movie theaters where The Great Train Robbery was shown in 1903.","detail":"They helped build early mass audiences for film.","year":1903,"difficulty":3,"aliases":[]},{"id":"a-026","kind":"concept","topics":["vocab","culture"],"chapter":30,"page":710,"term":"Hollywood","def":"Southern California community that became the movie capital.","detail":"Stars there earned up to $100,000 per picture, more than the president.","year":null,"difficulty":2,"aliases":[]},{"id":"a-027","kind":"concept","topics":["vocab","economy"],"chapter":30,"page":710,"term":"Advertising","def":"Industry that used persuasion and sexual suggestion to make Americans want more goods.","detail":"The first radio advertisement aired in August 1922.","year":1922,"difficulty":1,"aliases":["Mass consumption"]},{"id":"a-028","kind":"person","topics":["people","economy","culture"],"chapter":30,"page":710,"term":"Bruce Barton","def":"Advertising pioneer who wrote a 1925 best seller portraying Jesus as the greatest adman.","detail":"The book was titled The Man Nobody Knows.","year":1925,"difficulty":2,"aliases":["Barton"]},{"id":"a-029","kind":"person","topics":["people","culture"],"chapter":30,"page":710,"term":"Babe Ruth","def":"Home-run hero better known than most statesmen; Yankee Stadium was called the house that he built.","detail":"He was among the era\u0027s media-made celebrities.","year":null,"difficulty":2,"aliases":["Ruth"]},{"id":"a-030","kind":"person","topics":["people","culture"],"chapter":30,"page":710,"term":"Jack Dempsey","def":"Boxer whose 1921 knockout of Georges Carpentier produced one of the decade\u0027s first million-dollar gates.","detail":"He joined Ruth and Lindbergh as a celebrity.","year":1921,"difficulty":3,"aliases":["Dempsey"]},{"id":"a-031","kind":"person","topics":["people","culture"],"chapter":30,"page":711,"term":"Margaret Sanger","def":"Fiery feminist who promoted birth control and opened contraceptive clinics from 1912.","detail":"In 1929 Boston forbade her to speak, so she lectured with tape over her mouth.","year":1912,"difficulty":1,"aliases":["Sanger"],"key":["oct28"]},{"id":"a-032","kind":"concept","topics":["vocab","themes"],"chapter":30,"page":711,"term":"National Woman\u0027s Party","def":"Group led by Alice Paul beginning in 1923 to push for an Equal Rights Amendment.","detail":"The amendment was still not ratified nearly a century later.","year":1923,"difficulty":2,"aliases":["NWP"]},{"id":"a-033","kind":"person","topics":["people"],"chapter":30,"page":711,"term":"Alice Paul","def":"Feminist leader of the party that began in 1923 pressing for the Equal Rights Amendment.","detail":"She led the National Woman\u0027s Party.","year":1923,"difficulty":2,"aliases":["Paul"]},{"id":"a-034","kind":"concept","topics":["vocab","culture"],"chapter":30,"page":711,"term":"Flappers","def":"Young women with bobbed hair, short skirts, rouged cheeks, and cigarettes who symbolized 1920s independence.","detail":"They were called goddesses of the era of wonderful nonsense.","year":null,"difficulty":1,"aliases":["Flapper"],"key":["oct28"]},{"id":"a-035","kind":"person","topics":["people","culture"],"chapter":30,"page":711,"term":"Sigmund Freud","def":"Viennese physician whose translated writings argued sexual repression caused emotional illness.","detail":"His ideas helped frame sexual gratification as a health need.","year":null,"difficulty":2,"aliases":["Freud"]},{"id":"a-036","kind":"concept","topics":["vocab","culture"],"chapter":30,"page":711,"term":"Modernists","def":"Religious liberals who saw God as a good guy and the universe as pleasant, gaining ground over Fundamentalists.","detail":"They contrasted with advocates of old-time religion.","year":null,"difficulty":2,"aliases":["Modernism in religion"]},{"id":"a-037","kind":"concept","topics":["vocab","culture"],"chapter":30,"page":712,"term":"Jazz","def":"Native American music of wandering solos and syncopation that moved up from New Orleans with Black migrants.","detail":"Born with Handy, Morton, Armstrong, and Oliver; Paul Whiteman led a white band.","year":null,"difficulty":1,"aliases":[]},{"id":"a-038","kind":"person","topics":["people","culture"],"chapter":30,"page":712,"term":"W. C. Handy","def":"Black musician whose 1914 song St. Louis Blues became an instant classic.","detail":"He was among the founders of jazz.","year":1914,"difficulty":3,"aliases":["Handy"]},{"id":"a-039","kind":"person","topics":["people","culture"],"chapter":30,"page":712,"term":"Louis Armstrong","def":"Black performer counted among those who gave birth to jazz.","detail":"Others included Handy, Jelly Roll Morton, and King Oliver.","year":null,"difficulty":2,"aliases":["Armstrong"]},{"id":"a-040","kind":"person","topics":["people","culture"],"chapter":30,"page":711,"term":"Duke Ellington","def":"Jazz innovator who said jazz expressed the natural feelings of a people and the modern temper.","detail":"He argued today\u0027s people deserve their own music, not Beethoven\u0027s.","year":null,"difficulty":2,"aliases":["Ellington"]},{"id":"a-041","kind":"person","topics":["people","culture"],"chapter":30,"page":711,"term":"Henry van Dyke","def":"Traditionalist clergyman who condemned jazz as not music at all but willful ugliness.","detail":"He called it an irritation of the nerves of hearing.","year":null,"difficulty":3,"aliases":["Van Dyke"]},{"id":"a-042","kind":"event","topics":["events","culture"],"chapter":30,"page":712,"term":"Harlem Renaissance","def":"Flowering of Black culture in a New York neighborhood with about 150,000 African American residents in the 1920s.","detail":"Poet Langston Hughes published The Weary Blues in 1926.","year":1926,"difficulty":1,"aliases":["Harlem"],"key":["nov2"]},{"id":"a-043","kind":"person","topics":["people","culture"],"chapter":30,"page":712,"term":"Langston Hughes","def":"Harlem poet whose first volume, The Weary Blues, appeared in 1926.","detail":"He was part of Harlem\u0027s creative culture.","year":1926,"difficulty":1,"aliases":["Hughes"],"key":["nov2"]},{"id":"a-044","kind":"person","topics":["people"],"chapter":30,"page":712,"term":"Marcus Garvey","def":"Jamaican-born Black nationalist who led a self-help group and urged resettlement in an African homeland.","detail":"He was convicted of mail fraud in 1927 and deported.","year":1927,"difficulty":1,"aliases":["Garvey"]},{"id":"a-045","kind":"concept","topics":["vocab"],"chapter":30,"page":712,"term":"UNIA","def":"Garvey\u0027s nationalist group with 1,100 branches in 40 countries and about 4 million followers.","detail":"It ran businesses like the Black Star Line Steamship Company.","year":1920,"difficulty":1,"aliases":["Universal Negro Improvement Association","United Negro Improvement Association"],"key":["oct28"]},{"id":"a-046","kind":"concept","topics":["vocab","economy"],"chapter":30,"page":712,"term":"Black Star Line","def":"Steamship company sponsored by Garvey\u0027s movement to keep Black dollars in Black pockets.","detail":"Most of Garvey\u0027s enterprises failed financially.","year":null,"difficulty":3,"aliases":[]},{"id":"a-047","kind":"concept","topics":["vocab"],"chapter":30,"page":712,"term":"Nation of Islam","def":"Black Muslim movement whose later founding was influenced by Garvey\u0027s example.","detail":"Garvey\u0027s race pride gave followers self-confidence.","year":null,"difficulty":3,"aliases":["Black Muslims"]},{"id":"a-048","kind":"event","topics":["events","themes"],"chapter":30,"page":713,"term":"Red Scare","def":"1919-1920 nationwide crusade against suspected left-wing radicals after the Bolshevik Revolution and strikes.","detail":"It helped conservative businesses break fledgling unions.","year":1919,"difficulty":1,"aliases":["Great Red Scare"],"key":["oct28"]},{"id":"a-049","kind":"person","topics":["people"],"chapter":30,"page":713,"term":"A. Mitchell Palmer","def":"Attorney General who rounded up about 6,000 suspected radicals, nicknamed the Fighting Quaker.","detail":"A bomb hit his home in June 1919, making him the Quaking Fighter.","year":1919,"difficulty":1,"aliases":["Palmer"]},{"id":"a-050","kind":"event","topics":["events"],"chapter":30,"page":713,"term":"Buford deportation","def":"December 1919 ship carrying 249 alleged alien radicals to Russia, nicknamed the Soviet Ark.","detail":"The nickname Soviet Ark mocked the voyage.","year":1919,"difficulty":2,"aliases":["Soviet Ark","Buford"]},{"id":"a-051","kind":"event","topics":["events"],"chapter":30,"page":713,"term":"Wall Street bombing","def":"September 1920 unexplained blast that killed 38 and injured more than 100, reviving hysteria.","detail":"It occurred amid the Red Scare.","year":1920,"difficulty":3,"aliases":[]},{"id":"a-052","kind":"law","topics":["vocab"],"chapter":30,"page":713,"term":"Criminal syndicalism laws","def":"State laws of 1919-1920 outlawing advocacy of violence to change society.","detail":"Critics said words are not deeds.","year":1919,"difficulty":2,"aliases":[]},{"id":"a-053","kind":"concept","topics":["vocab","economy"],"chapter":30,"page":713,"term":"Open shop","def":"Employer-backed policy called the American plan, opposing all-union closed shops.","detail":"Closed shops were attacked as Sovietism in disguise.","year":null,"difficulty":2,"aliases":["American plan"]},{"id":"a-054","kind":"event","topics":["events"],"chapter":30,"page":713,"term":"Sacco and Vanzetti case","def":"Trial of two Italian anarchists for a Massachusetts murder that liberals called a judicial lynching.","detail":"They were convicted in 1921 and electrocuted in 1927.","year":1921,"difficulty":1,"aliases":["Sacco-Vanzetti"],"key":["oct28"]},{"id":"a-055","kind":"person","topics":["people"],"chapter":30,"page":713,"term":"Nicola Sacco","def":"Italian shoe worker convicted with a fish peddler of a Massachusetts paymaster murder.","detail":"Executed in 1927 after worldwide protest.","year":1921,"difficulty":3,"aliases":["Sacco"]},{"id":"a-056","kind":"person","topics":["people"],"chapter":30,"page":713,"term":"Bartolomeo Vanzetti","def":"Italian fish peddler and anarchist convicted of murder in Massachusetts alongside a shoe worker.","detail":"Jury and judge were prejudiced against Italians and radicals.","year":1921,"difficulty":3,"aliases":["Vanzetti"]},{"id":"a-057","kind":"concept","topics":["vocab","themes"],"chapter":30,"page":713,"term":"Ku Klux Klan","def":"1920s revival of a hooded order against Catholics, Jews, Blacks, immigrants, and modernity, peaking at about 5 million members.","detail":"Strongest among white Protestants in the Midwest and South.","year":null,"difficulty":1,"aliases":["KKK","Klan"],"key":["oct28"]},{"id":"a-058","kind":"person","topics":["people"],"chapter":30,"page":713,"term":"Hiram Wesley Evans","def":"Imperial Wizard of the KKK who in 1926 described it as a movement of plain people.","detail":"He admitted critics called members hicks and rubes.","year":1926,"difficulty":3,"aliases":["Evans"]},{"id":"a-059","kind":"law","topics":["vocab","themes"],"chapter":30,"page":714,"term":"Immigration Act of 1924","def":"Law limiting immigrants to 2% of each nationality in the 1890 census and shutting out Japanese.","detail":"Britain could send 65,721 a year versus 5,802 for Italy.","year":1924,"difficulty":1,"aliases":["National Origins Act","Johnson-Reed Act"],"key":["oct28"]},{"id":"a-060","kind":"concept","topics":["vocab"],"chapter":30,"page":714,"term":"New Immigration","def":"Wave of newcomers from southern and eastern Europe that nativists feared.","detail":"Two-thirds of the 800,000 arrivals in 1920-1921 came from there.","year":1921,"difficulty":2,"aliases":[]},{"id":"a-061","kind":"law","topics":["vocab"],"chapter":30,"page":714,"term":"Immigration Act of 1929","def":"Law using 1920 as quota base and cutting total immigration to 152,574 a year.","detail":"It roughly halved annual immigration.","year":1929,"difficulty":3,"aliases":["National Origins Provision"]},{"id":"a-062","kind":"law","topics":["vocab","themes"],"chapter":30,"page":715,"term":"Indian Citizenship Act","def":"Law granting citizenship to all Native Americans born in the US.","detail":"It did not guarantee voting rights, which stayed under state law.","year":1924,"difficulty":1,"aliases":["Indian Citizenship Act of 1924"],"key":["oct28"]},{"id":"a-063","kind":"concept","topics":["vocab","themes"],"chapter":30,"page":716,"term":"Cultural pluralism","def":"View opposing the melting pot, holding that ethnic groups should keep their distinctive cultures.","detail":"Horace Kallen compared groups to instruments in a symphony orchestra.","year":null,"difficulty":2,"aliases":["Pluralism"]},{"id":"a-064","kind":"person","topics":["people"],"chapter":30,"page":716,"term":"Horace Kallen","def":"Philosopher who saw the US as a protective canopy letting ethnic groups keep their uniqueness.","detail":"He used the metaphor of a symphony orchestra.","year":null,"difficulty":3,"aliases":["Kallen"]},{"id":"a-065","kind":"person","topics":["people"],"chapter":30,"page":716,"term":"Randolph Bourne","def":"Writer who envisioned America as a trans-nationality woven from many colored threads.","detail":"He favored cross-fertilization among cultures.","year":null,"difficulty":3,"aliases":["Bourne"]},{"id":"a-066","kind":"law","topics":["vocab"],"chapter":30,"page":716,"term":"Eighteenth Amendment","def":"Constitutional change that banned alcoholic beverages, ratified 1919.","detail":"The Volstead Act enforced it.","year":1919,"difficulty":1,"aliases":["Prohibition amendment","18th Amendment","Prohibition"],"key":["oct28"]},{"id":"a-067","kind":"law","topics":["vocab"],"chapter":30,"page":716,"term":"Volstead Act","def":"1919 law that provided enforcement of the national ban on alcohol.","detail":"Critics said it made the world safe for hypocrisy.","year":1919,"difficulty":1,"aliases":[]},{"id":"a-068","kind":"concept","topics":["vocab","culture"],"chapter":30,"page":717,"term":"Speakeasies","def":"Illegal drinking spots with grilled windows and passwords that replaced corner saloons.","detail":"Thousands appeared during Prohibition.","year":null,"difficulty":2,"aliases":["Speakeasy"]},{"id":"a-069","kind":"concept","topics":["vocab"],"chapter":30,"page":717,"term":"Bootlegging","def":"Illegal production and sale of liquor during Prohibition, including rum-running from the West Indies and Canada.","detail":"It produced huge profits and police bribery.","year":null,"difficulty":2,"aliases":["Rum-running"]},{"id":"a-070","kind":"person","topics":["people"],"chapter":30,"page":717,"term":"Al Capone","def":"Scarface Chicago booze distributor who began six years of gang warfare in 1925.","detail":"Jailed in 1932 for income-tax evasion rather than the St. Valentine\u0027s Day Massacre.","year":1925,"difficulty":1,"aliases":["Scarface","Capone"],"key":["oct28"]},{"id":"a-071","kind":"event","topics":["events"],"chapter":30,"page":717,"term":"St. Valentine\u0027s Day Massacre","def":"1929 Chicago killing of seven rival gang members for which Capone was never convicted.","detail":"Capone was instead jailed for tax evasion.","year":1929,"difficulty":2,"aliases":[]},{"id":"a-072","kind":"concept","topics":["vocab","economy"],"chapter":30,"page":717,"term":"Organized crime","def":"Gangster rackets in alcohol, gambling, narcotics, and protection with an estimated $12-18 billion annual take by 1930.","detail":"This was several times the federal government\u0027s income.","year":1930,"difficulty":2,"aliases":["Racketeering"]},{"id":"a-073","kind":"person","topics":["people","culture"],"chapter":30,"page":718,"term":"John Dewey","def":"Columbia professor who promoted learning by doing and progressive education.","detail":"He said a workbench was as essential as a blackboard.","year":null,"difficulty":2,"aliases":["Dewey"]},{"id":"a-074","kind":"event","topics":["events","culture"],"chapter":30,"page":718,"term":"Scopes Trial","def":"1925 Dayton, Tennessee, trial of a teacher charged with teaching evolution.","detail":"Scopes was fined $100; the fine was overturned on a technicality.","year":1925,"difficulty":1,"aliases":["Monkey Trial","Scopes Monkey Trial"],"key":["oct28"]},{"id":"a-075","kind":"person","topics":["people"],"chapter":30,"page":718,"term":"John T. Scopes","def":"High-school biology teacher indicted for teaching evolution in Tennessee.","detail":"Found guilty and fined $100.","year":1925,"difficulty":2,"aliases":["Scopes"]},{"id":"a-076","kind":"person","topics":["people"],"chapter":30,"page":718,"term":"Clarence Darrow","def":"Famed defense attorney in the Scopes Trial who made his opponent look foolish.","detail":"He questioned Bryan about the Bible.","year":1925,"difficulty":2,"aliases":["Darrow"]},{"id":"a-077","kind":"person","topics":["people"],"chapter":30,"page":718,"term":"William Jennings Bryan","def":"Former presidential candidate and Fundamentalist who prosecuted Scopes and died days after the trial.","detail":"He died of a stroke five days after the trial ended.","year":1925,"difficulty":1,"aliases":["Bryan"]},{"id":"a-078","kind":"concept","topics":["vocab","culture"],"chapter":30,"page":718,"term":"Fundamentalism","def":"Strict literal Bible faith that attacked Darwinian evolution and progressive education in the 1920s.","detail":"Stayed strong in the Baptist Church and Churches of Christ.","year":null,"difficulty":1,"aliases":["Fundamentalists"],"key":["oct28"]},{"id":"a-079","kind":"person","topics":["people","culture"],"chapter":30,"page":719,"term":"H. L. Mencken","def":"Bad Boy of Baltimore, influential critic who mocked the South as the Sahara of the Bozart and attacked the booboisie.","detail":"He called Puritanism the fear that someone might be happy.","year":null,"difficulty":1,"aliases":["Mencken"]},{"id":"a-080","kind":"person","topics":["people","culture"],"chapter":30,"page":719,"term":"F. Scott Fitzgerald","def":"Minnesota-born author of This Side of Paradise, the bible of young flappers, and The Great Gatsby.","detail":"The Great Gatsby (1925) critiques the illusion of self-made success.","year":1920,"difficulty":1,"aliases":["Fitzgerald"]},{"id":"a-081","kind":"concept","topics":["vocab","culture"],"chapter":30,"page":719,"term":"The Great Gatsby","def":"1925 novel in which self-made Jay Gatsby is destroyed by old wealth and social standing.","detail":"It critiques the American ideal of self-made success.","year":1925,"difficulty":1,"aliases":["Great Gatsby"],"key":["nov2"]},{"id":"a-082","kind":"person","topics":["people","culture"],"chapter":30,"page":719,"term":"Theodore Dreiser","def":"Author of An American Tragedy, a 1925 novel on the pitfalls of social striving.","detail":"Published the same year as The Great Gatsby.","year":1925,"difficulty":3,"aliases":["Dreiser"]},{"id":"a-083","kind":"person","topics":["people","culture"],"chapter":30,"page":720,"term":"Ernest Hemingway","def":"Lean-style author shaped by the Italian front who wrote The Sun Also Rises and A Farewell to Arms.","detail":"Won the 1954 Nobel Prize; died by suicide in 1961.","year":1926,"difficulty":1,"aliases":["Hemingway"]},{"id":"a-084","kind":"concept","topics":["vocab","culture"],"chapter":30,"page":720,"term":"Lost Generation","def":"American writers and painters who lived as expatriates in postwar Europe, including Hemingway and Fitzgerald.","detail":"They were disillusioned by the war.","year":null,"difficulty":1,"aliases":[],"key":["nov2"]},{"id":"a-085","kind":"person","topics":["people","culture"],"chapter":30,"page":720,"term":"Gertrude Stein","def":"Paris salon host who applied stream of consciousness to literature.","detail":"Wrote Three Lives, Tender Buttons, and The Autobiography of Alice B. Toklas.","year":null,"difficulty":3,"aliases":["Stein"]},{"id":"a-086","kind":"person","topics":["people","culture"],"chapter":30,"page":720,"term":"Ezra Pound","def":"Idaho-born poet who left America for Europe and urged to Make It New.","detail":"Counted among the high modernists.","year":null,"difficulty":3,"aliases":["Pound"]},{"id":"a-087","kind":"person","topics":["people","culture"],"chapter":30,"page":720,"term":"T. S. Eliot","def":"Missouri-born poet who became a British citizen and wrote The Waste Land in 1922.","detail":"The poem is a dense, fragmented work of postwar desolation.","year":1922,"difficulty":2,"aliases":["Eliot"]},{"id":"a-088","kind":"person","topics":["people","culture"],"chapter":30,"page":720,"term":"Sinclair Lewis","def":"Novelist of Main Street and Babbitt, satirizing small-town and middle-class provincialism.","detail":"His real-estate-broker character gave rise to the word Babbittry.","year":1920,"difficulty":2,"aliases":["Lewis"]},{"id":"a-089","kind":"person","topics":["people","culture"],"chapter":30,"page":720,"term":"William Faulkner","def":"Mississippi novelist of fictional Yoknapatawpha County who wrote about the Old South\u0027s displacement by industry.","detail":"Works include The Sound and the Fury (1929) and As I Lay Dying (1930).","year":1929,"difficulty":2,"aliases":["Faulkner"]},{"id":"a-090","kind":"concept","topics":["vocab","culture"],"chapter":30,"page":719,"term":"Modernism","def":"Cultural movement questioning social conventions and traditional authority as outmoded.","detail":"It gave American arts new daring after WWI.","year":null,"difficulty":2,"aliases":["Modernist"]},{"id":"b-002","kind":"event","topics":["culture","events"],"chapter":30,"page":721,"term":"Show Boat","def":"Kern and Hammerstein Broadway production regarded as the first true American musical play.","detail":"Written by Jerome Kern and Oscar Hammerstein.","year":1927,"difficulty":3,"aliases":[]},{"id":"b-003","kind":"person","topics":["culture","people"],"chapter":30,"page":721,"term":"Eugene O\u0027Neill","def":"Princeton dropout from Greenwich Village who became America\u0027s first world-class playwright.","detail":"His Strange Interlude (1928) used Freudian ideas; he won the Nobel Prize in Literature in 1936.","year":1936,"difficulty":2,"aliases":["Eugene ONeill","O\u0027Neill","ONeill"]},{"id":"b-004","kind":"concept","topics":["culture","vocab"],"chapter":30,"page":721,"term":"Strange Interlude","def":"O\u0027Neill play that used soliloquies to explore Freudian ideas about sex and the subconscious.","detail":"Part of more than a dozen O\u0027Neill productions in the 1920s.","year":1928,"difficulty":3,"aliases":[]},{"id":"b-007","kind":"concept","topics":["culture","vocab"],"chapter":30,"page":721,"term":"Greenwich Village","def":"New York neighborhood that was a cauldron of writers, painters, musicians and actors before and after World War I.","detail":"Eugene O\u0027Neill came out of this community.","year":null,"difficulty":3,"aliases":[]},{"id":"b-009","kind":"concept","topics":["culture","vocab"],"chapter":30,"page":721,"term":"New Negro","def":"Ideal promoted by black artists of the 1920s of a full citizen and social equal of whites.","detail":"Advanced by Harlem Renaissance writers.","year":null,"difficulty":2,"aliases":[]},{"id":"b-010","kind":"person","topics":["culture","people"],"chapter":30,"page":721,"term":"Claude McKay","def":"Harlem Renaissance leader among the writers who celebrated black culture after World War I.","detail":"Named with Hughes and Hurston as a leader.","year":null,"difficulty":3,"aliases":[]},{"id":"b-011","kind":"person","topics":["culture","people"],"chapter":30,"page":721,"term":"Zora Neale Hurston","def":"Harlem Renaissance writer who used modernist techniques to capture oral black traditions in dialect-filled prose.","detail":"Shared this approach with Langston Hughes.","year":null,"difficulty":2,"aliases":["Hurston"]},{"id":"b-013","kind":"person","topics":["culture","people"],"chapter":30,"page":721,"term":"Eubie Blake","def":"Jazz musician linked to the postwar black cultural renaissance in Harlem.","detail":"Mentioned with Louis Armstrong.","year":null,"difficulty":3,"aliases":[]},{"id":"b-014","kind":"event","topics":["economy","events"],"chapter":30,"page":721,"term":"Florida land boom","def":"Real estate speculation frenzy in which even underwater lots sold for huge sums before a hurricane devastated the peninsula.","detail":"Peaked in 1925; a West Indian hurricane hit the state.","year":1925,"difficulty":2,"aliases":["Florida real estate boom"]},{"id":"b-015","kind":"concept","topics":["economy","vocab"],"chapter":30,"page":721,"term":"Bull market","def":"Period of wild stock speculation in the 1920s, driven by slogans like \u0027Never sell America short\u0027.","detail":"Several hundred banks failed yearly even in the best 1920s years.","year":null,"difficulty":1,"aliases":["bull"],"key":["nov2"]},{"id":"b-016","kind":"person","topics":["economy","people"],"chapter":30,"page":722,"term":"Calvin Coolidge","def":"Vermont-born Republican president known as \u0027Silent Cal\u0027 who let business have its head.","detail":"He took office after Harding died in 1923; Hoover called him a conservative even in fishing.","year":null,"difficulty":1,"aliases":["Coolidge","Silent Cal"]},{"id":"b-017","kind":"law","topics":["economy","vocab"],"chapter":30,"page":722,"term":"Bureau of the Budget","def":"Agency created by Congress to help the president prepare estimates of government receipts and expenditures.","detail":"Created by a Republican Congress in 1921.","year":1921,"difficulty":2,"aliases":[]},{"id":"b-018","kind":"person","topics":["economy","people"],"chapter":30,"page":722,"term":"Andrew Mellon","def":"Millionaire Treasury secretary who engineered large tax cuts and cut the national debt.","detail":"Cut debt from about $26 billion to $16 billion; shifted tax burden to middle incomes.","year":null,"difficulty":1,"aliases":["Mellon"]},{"id":"b-019","kind":"concept","topics":["economy","vocab"],"chapter":30,"page":722,"term":"Mellon tax cuts","def":"Policy cutting income taxes so a $1 million earner paid about $200,000 instead of $663,000.","detail":"The $663,000 figure was from 1921; the $200,000 from 1926.","year":1926,"difficulty":2,"aliases":["Mellon tax policy"]},{"id":"b-020","kind":"person","topics":["people"],"chapter":30,"page":722,"term":"Warren G. Harding","def":"Good-looking, well-liked Ohio president with a mediocre mind who was surrounded by corrupt cronies.","detail":"He cried \u0027God! What a job!\u0027 and died in office in 1923.","year":1921,"difficulty":1,"aliases":["Harding"],"key":["nov2"]},{"id":"b-021","kind":"concept","topics":["vocab"],"chapter":30,"page":723,"term":"Ohio Gang","def":"Poker-playing cronies around Harding whom he could not recognize as corrupt.","detail":"Compared to Grant\u0027s associates.","year":null,"difficulty":1,"aliases":[],"key":["nov2"]},{"id":"b-022","kind":"person","topics":["people"],"chapter":30,"page":723,"term":"Charles Evans Hughes","def":"Harding\u0027s secretary of state, counted among the cabinet\u0027s best minds, who proposed a naval holiday.","detail":"Also told Europe America was staying home.","year":null,"difficulty":2,"aliases":[]},{"id":"b-023","kind":"person","topics":["economy","people"],"chapter":30,"page":723,"term":"Herbert Hoover","def":"Harding\u0027s Commerce secretary and later president, a self-made engineer who preached rugged individualism.","detail":"Won 1928 landslide, 444 to 87 electoral votes.","year":1928,"difficulty":1,"aliases":["Hoover"],"key":["nov4"]},{"id":"b-024","kind":"person","topics":["people"],"chapter":30,"page":723,"term":"Albert B. Fall","def":"New Mexico senator and Interior secretary who took bribes for leasing naval oil reserves.","detail":"Found guilty of bribery and sentenced to one year in jail.","year":null,"difficulty":1,"aliases":["Fall","Albert Fall"]},{"id":"b-025","kind":"person","topics":["people"],"chapter":30,"page":723,"term":"Harry Daugherty","def":"Harding\u0027s corrupt attorney general investigated in 1924 for selling pardons and liquor permits.","detail":"Forced to resign by Coolidge; Hoover said he should never have been in government.","year":null,"difficulty":2,"aliases":["Daugherty","Harry M. Daugherty"]},{"id":"b-026","kind":"person","topics":["people"],"chapter":30,"page":723,"term":"William Howard Taft","def":"Former president who served as chief justice during the Harding era and was more liberal than some colleagues.","detail":"Harding appointed four of nine justices in under three years.","year":null,"difficulty":3,"aliases":["Taft"]},{"id":"b-027","kind":"concept","topics":["economy","vocab"],"chapter":30,"page":723,"term":"Old Guard","def":"Conservative Republican leadership of the 1920s that crushed progressive reform and aided business.","detail":"Placed courts and agencies in pro-business hands.","year":null,"difficulty":2,"aliases":["Republican Old Guard"]},{"id":"b-028","kind":"law","topics":["economy","vocab"],"chapter":30,"page":723,"term":"Adkins v. Children\u0027s Hospital","def":"Supreme Court ruling striking down a women\u0027s minimum-wage law because women now had the vote.","detail":"Reversed Muller v. Oregon (1908); Holmes dissented.","year":1923,"difficulty":1,"aliases":["Adkins"]},{"id":"b-029","kind":"law","topics":["economy","vocab"],"chapter":30,"page":723,"term":"Muller v. Oregon","def":"Earlier ruling allowing special protective laws for women workers, later reversed by the Court.","detail":"Reversed by the 1923 Adkins decision.","year":1908,"difficulty":3,"aliases":[]},{"id":"b-030","kind":"person","topics":["people"],"chapter":30,"page":723,"term":"Oliver Wendell Holmes","def":"Justice who dissented in Adkins, saying the Nineteenth Amendment did not erase male-female differences.","detail":"Dissent targeted the minimum-wage decision.","year":1923,"difficulty":3,"aliases":["Holmes"]},{"id":"b-031","kind":"law","topics":["economy","vocab"],"chapter":30,"page":724,"term":"Esch-Cummins Act","def":"Law returning railroads to private management and pledging the ICC to guarantee their profitability.","detail":"Encouraged railroad consolidation.","year":1920,"difficulty":2,"aliases":["Esch-Cummins Transportation Act"]},{"id":"b-032","kind":"event","topics":["economy","events"],"chapter":30,"page":724,"term":"Railway Labor Board strike","def":"Two-month walkout provoked by a ruling ordering a 12 percent wage cut.","detail":"Union membership fell nearly 30 percent from 1920 to 1930.","year":1922,"difficulty":3,"aliases":["railroad strike"]},{"id":"b-033","kind":"event","topics":["economy","events"],"chapter":30,"page":724,"term":"Steel strike","def":"Walkout broken by employers who exploited ethnic divisions and called strikers dangerous reds.","detail":"Part of labor\u0027s struggles in the postwar decade.","year":1919,"difficulty":3,"aliases":["steel strike"]},{"id":"b-034","kind":"law","topics":["vocab"],"chapter":30,"page":724,"term":"Veterans Bureau","def":"Agency created by Congress to run hospitals and rehabilitation for disabled veterans.","detail":"Its head Charles Forbes looted nearly $200 million.","year":1921,"difficulty":3,"aliases":[]},{"id":"b-035","kind":"concept","topics":["vocab"],"chapter":30,"page":724,"term":"American Legion","def":"Veterans\u0027 group founded in Paris by Theodore Roosevelt Jr., known for militant patriotism and anti-radicalism.","detail":"Lobbied hard for a veterans\u0027 bonus.","year":1919,"difficulty":1,"aliases":[],"key":["nov2"]},{"id":"b-036","kind":"law","topics":["economy","vocab"],"chapter":30,"page":724,"term":"Adjusted Compensation Act","def":"Law giving veterans paid-up insurance policies due in 20 years, passed over Coolidge\u0027s veto.","detail":"Cost about $3.5 billion.","year":1924,"difficulty":2,"aliases":["Bonus Act","veterans bonus"]},{"id":"b-037","kind":"event","topics":["events"],"chapter":30,"page":725,"term":"Washington Naval Conference","def":"Gathering of naval powers (excluding Bolshevik Russia) addressing disarmament and the Far East.","detail":"Hughes proposed a ten-year battleship building holiday.","year":1921,"difficulty":1,"aliases":["Washington Disarmament Conference","Washington Conference"],"key":["nov2"]},{"id":"b-038","kind":"concept","topics":["vocab"],"chapter":30,"page":725,"term":"5:5:3 ratio","def":"Hughes\u0027s proposed battleship and carrier ratio for the US, Britain and Japan.","detail":"Japan\u0027s ambassador objected to the Rolls-Royce, Rolls-Royce, Ford comparison.","year":1921,"difficulty":2,"aliases":["5-5-3"]},{"id":"b-039","kind":"law","topics":["vocab"],"chapter":30,"page":725,"term":"Five-Power Naval Treaty","def":"Agreement limiting battleships in which Britain and the US agreed not to fortify Far Eastern possessions.","detail":"Japan was not held to this; small warships were unrestricted.","year":1922,"difficulty":2,"aliases":["Five-Power Treaty"]},{"id":"b-040","kind":"law","topics":["vocab"],"chapter":30,"page":725,"term":"Four-Power Treaty","def":"Pact among Britain, Japan, France and the US to preserve the status quo in the Pacific.","detail":"Part of the Washington Conference.","year":1922,"difficulty":3,"aliases":[]},{"id":"b-041","kind":"law","topics":["vocab"],"chapter":30,"page":725,"term":"Nine-Power Treaty","def":"Washington Conference agreement that nailed open the Door in China.","detail":"China was called the Sick Man of the Far East.","year":1922,"difficulty":2,"aliases":[]},{"id":"b-042","kind":"law","topics":["vocab"],"chapter":30,"page":725,"term":"Kellogg-Briand Pact","def":"\u0027Outlawry of war\u0027 agreement ratified by 62 nations but with no enforcement and defensive wars allowed.","detail":"Frank Kellogg later won the Nobel Peace Prize.","year":1928,"difficulty":1,"aliases":["Pact of Paris"],"key":["nov2"]},{"id":"b-043","kind":"person","topics":["people"],"chapter":30,"page":725,"term":"Frank B. Kellogg","def":"Secretary of State who co-signed the outlawry-of-war pact and later won a Nobel Peace Prize.","detail":"Signed with the French foreign minister.","year":1928,"difficulty":3,"aliases":["Kellogg"]},{"id":"b-044","kind":"law","topics":["economy","vocab"],"chapter":30,"page":726,"term":"Fordney-McCumber Tariff","def":"Republican tariff raising average rates to 38.5 percent and squeezing European producers.","detail":"Europeans copied American barriers through the 1920s.","year":1922,"difficulty":1,"aliases":["Fordney-McCumber Tariff Law"]},{"id":"b-045","kind":"person","topics":["people"],"chapter":30,"page":726,"term":"Charles Forbes","def":"Veterans Bureau head and ex-army deserter who looted nearly $200 million, mostly in hospital construction.","detail":"Sentenced to two years in prison.","year":1923,"difficulty":2,"aliases":["Forbes","Charles R. Forbes"]},{"id":"b-046","kind":"event","topics":["economy","events"],"chapter":30,"page":726,"term":"Teapot Dome scandal","def":"Scandal where Interior Secretary Fall secretly leased naval oil reserves to private oilmen for bribes.","detail":"Reserves in Wyoming and Elk Hills, California; leaked March 1923.","year":1923,"difficulty":1,"aliases":["Teapot Dome"],"key":["nov2"]},{"id":"b-047","kind":"person","topics":["people"],"chapter":30,"page":726,"term":"Harry Sinclair","def":"Oilman who leased naval reserves from Fall and gave him roughly $300,000 in all.","detail":"Indicted in 1924 with Fall and Doheny.","year":null,"difficulty":3,"aliases":["Harry F. Sinclair"]},{"id":"b-048","kind":"person","topics":["people"],"chapter":30,"page":726,"term":"Edward Doheny","def":"Oilman who gave Albert Fall a $100,000 \u0027loan\u0027 tied to naval oil leases.","detail":"Indicted in 1924; case lasted until 1929.","year":null,"difficulty":3,"aliases":["Edward L. Doheny","Doheny"]},{"id":"b-049","kind":"concept","topics":["vocab"],"chapter":30,"page":726,"term":"Elk Hills","def":"California naval oil reserve transferred to Interior and leased out in the Harding scandal.","detail":"Linked with the Wyoming reserve.","year":null,"difficulty":3,"aliases":[]},{"id":"b-050","kind":"event","topics":["events"],"chapter":30,"page":726,"term":"Harding\u0027s death","def":"Event in which the vice president learned of the president\u0027s death at his father\u0027s Vermont farmhouse and took the oath from his father.","detail":"Harding died August 2, 1923, in San Francisco.","year":1923,"difficulty":2,"aliases":["Harding death"]},{"id":"b-051","kind":"event","topics":["economy","events"],"chapter":30,"page":732,"term":"Black Tuesday","def":"Day of orgy-like stock selling with over 16 million shares traded as the market collapsed.","detail":"Occurred October 29, 1929; 16,410,030 shares sold.","year":1929,"difficulty":1,"aliases":["Black Tuesday"],"key":["nov4"]},{"id":"b-052","kind":"concept","topics":["economy","vocab"],"chapter":30,"page":727,"term":"Farm bloc","def":"Bipartisan group from agricultural states in Congress seeking relief and cooperative antitrust exemptions.","detail":"Formed in 1921.","year":1921,"difficulty":2,"aliases":[]},{"id":"b-053","kind":"law","topics":["economy","vocab"],"chapter":30,"page":727,"term":"McNary-Haugen Bill","def":"Farm relief plan to buy surpluses and sell them abroad, vetoed twice by Coolidge.","detail":"Losses to be covered by a special tax on farmers; pushed 1924-1928.","year":1924,"difficulty":1,"aliases":["McNary-Haugen"],"key":["nov2"]},{"id":"b-054","kind":"concept","topics":["economy","vocab"],"chapter":30,"page":727,"term":"Steel mule","def":"Nickname for the gasoline tractor that replaced horse-drawn plows and produced surplus crops.","detail":"Farmers owned ten times more by 1930 than 1920.","year":null,"difficulty":3,"aliases":["tractor"]},{"id":"b-055","kind":"person","topics":["people"],"chapter":30,"page":728,"term":"John W. Davis","def":"Wealthy corporation lawyer tied to J.P. Morgan nominated by Democrats after 102 ballots.","detail":"Lost to Coolidge 15.7 million to 8.4 million votes.","year":1924,"difficulty":2,"aliases":["Davis"]},{"id":"b-056","kind":"person","topics":["people"],"chapter":30,"page":728,"term":"Robert La Follette","def":"Wisconsin senator, age 69, who ran as Progressive in 1924 backed by the AFL and farmers.","detail":"Won nearly 5 million votes and 13 electoral votes.","year":1924,"difficulty":1,"aliases":["La Follette","Robert M. La Follette"]},{"id":"b-057","kind":"event","topics":["events"],"chapter":30,"page":728,"term":"Coolidge-Davis-La Follette race","def":"Three-way presidential race won by Coolidge with 382 electoral votes over Davis and La Follette.","detail":"Democrats failed by one vote to condemn the Klan.","year":1924,"difficulty":1,"aliases":["election of 1924","1924 election"],"key":["nov2"]},{"id":"b-058","kind":"concept","topics":["vocab"],"chapter":30,"page":728,"term":"Progressive platform","def":"Platform calling for government-owned railroads, relief for farmers and a limit on the Supreme Court\u0027s power to void laws.","detail":"Also attacked monopoly and antilabor injunctions.","year":1924,"difficulty":3,"aliases":[]},{"id":"b-059","kind":"law","topics":["economy","vocab"],"chapter":30,"page":730,"term":"Dawes Plan","def":"Arrangement that rescheduled German reparations and opened the way for more American private loans to Germany.","detail":"Negotiated largely by Charles Dawes, later Coolidge\u0027s running mate.","year":1924,"difficulty":1,"aliases":[],"key":["nov2"]},{"id":"b-060","kind":"concept","topics":["economy","vocab"],"chapter":30,"page":729,"term":"Creditor nation","def":"Status America reached by 1922 after being a roughly $4 billion debtor in 1914.","detail":"US held about $16 billion in foreign assets by 1922.","year":1922,"difficulty":2,"aliases":[]},{"id":"b-061","kind":"concept","topics":["economy","vocab"],"chapter":30,"page":730,"term":"War debts tangle","def":"Cycle of reparations, private loans and Allied repayments to the US Treasury that collapsed after 1929.","detail":"The US loaned the Allies about $10 billion; Coolidge said \u0027They hired the money, didn\u0027t they?\u0027","year":null,"difficulty":1,"aliases":["war debts","financial merry-go-round"]},{"id":"b-062","kind":"concept","topics":["economy","vocab"],"chapter":30,"page":730,"term":"German reparations","def":"Payments the Allies demanded from Germany, about $32 billion, to repay US debts.","detail":"France occupied the Ruhr in 1923 to enforce them.","year":null,"difficulty":2,"aliases":["reparations"]},{"id":"b-063","kind":"event","topics":["economy","events"],"chapter":30,"page":730,"term":"Ruhr occupation","def":"French troops entered this German valley to force reparations payments.","detail":"German inflation hit 480 million marks for a loaf of bread by October.","year":1923,"difficulty":2,"aliases":["Ruhr Valley"]},{"id":"b-064","kind":"event","topics":["economy","events"],"chapter":30,"page":730,"term":"Hoover moratorium","def":"One-year suspension of war debt payments declared by the president.","detail":"Only Finland kept paying until 1976.","year":1931,"difficulty":2,"aliases":["debt moratorium"]},{"id":"b-065","kind":"event","topics":["events"],"chapter":30,"page":730,"term":"Marines in Nicaragua","def":"Coolidge returned some 5,000 troops to a Central American country after briefly removing them in 1925.","detail":"They stayed until 1933; troops had been there since 1909.","year":1926,"difficulty":3,"aliases":["Nicaragua intervention"]},{"id":"b-066","kind":"person","topics":["people"],"chapter":30,"page":731,"term":"Al Smith","def":"Four-time New York governor, wet Catholic Democrat, 1928 nominee called the Happy Warrior.","detail":"Lost 444 to 87 in the electoral vote.","year":1928,"difficulty":1,"aliases":["Alfred E. Smith","Smith"]},{"id":"b-067","kind":"event","topics":["events"],"chapter":30,"page":731,"term":"Hoover-Smith race","def":"Presidential race in which a Republican landslide cracked the Solid South amid anti-Catholic bigotry.","detail":"Hoover 21.4 million popular votes vs. Smith 15 million.","year":1928,"difficulty":1,"aliases":["election of 1928","1928 election"]},{"id":"b-068","kind":"concept","topics":["themes","vocab"],"chapter":30,"page":731,"term":"Rugged individualism","def":"Philosophy of self-reliance and limited government that Hoover championed and used to resist handouts.","detail":"He praised the \u0027American system\u0027 of it in 1928.","year":1928,"difficulty":1,"aliases":["rugged individualist"],"key":["nov4"]},{"id":"b-069","kind":"law","topics":["economy","vocab"],"chapter":30,"page":732,"term":"Agricultural Marketing Act","def":"Law creating a board with a $500 million revolving fund to help farm cooperatives hold surpluses.","detail":"Overwhelmed when wheat fell to 7 cents and cotton to 5 cents.","year":1929,"difficulty":2,"aliases":[]},{"id":"b-070","kind":"concept","topics":["economy","vocab"],"chapter":30,"page":732,"term":"Federal Farm Board","def":"Agency lending to farm organizations to buy, sell and store surpluses, soon overwhelmed by produce.","detail":"Had a $500 million revolving fund.","year":1929,"difficulty":2,"aliases":[]},{"id":"b-071","kind":"law","topics":["economy","vocab"],"chapter":30,"page":732,"term":"Hawley-Smoot Tariff","def":"Highest peacetime protective tariff in US history with duties averaging about 60 percent.","detail":"Deepened depression and angered foreign nations.","year":1930,"difficulty":1,"aliases":["Hawley-Smoot"],"key":["nov4"]},{"id":"b-072","kind":"event","topics":["economy","events"],"chapter":30,"page":732,"term":"Great Crash","def":"October 1929 stock collapse, partly triggered by Britain raising interest rates, that ended the Golden Twenties.","detail":"Stockholders lost $40 billion in paper values by year\u0027s end.","year":1929,"difficulty":1,"aliases":["Crash of 1929","Stock Market Crash"]},{"id":"b-073","kind":"concept","topics":["economy","vocab"],"chapter":30,"page":734,"term":"Gold standard","def":"Monetary system adopted by major powers after WWI that tied economies together and spread the depression.","detail":"Called a straitjacket.","year":null,"difficulty":3,"aliases":[]},{"id":"b-074","kind":"concept","topics":["economy","vocab"],"chapter":30,"page":734,"term":"Federal Reserve high interest rates","def":"Policy fearing a new bubble that squeezed money supply and turned the crash into a financial conflagration.","detail":"Made borrowing prohibitively expensive.","year":null,"difficulty":3,"aliases":["Fed policy"]},{"id":"b-075","kind":"event","topics":["economy","events"],"chapter":30,"page":734,"term":"Vienna bank failure","def":"Collapse of a prominent European bank that set off a chain reaction rattling America\u0027s banking system.","detail":"Part of the depression\u0027s global spread.","year":1931,"difficulty":3,"aliases":[]},{"id":"b-076","kind":"concept","topics":["economy","vocab"],"chapter":30,"page":735,"term":"Hooverville","def":"Shantytowns of scavenged materials built by homeless people early in the depression.","detail":"Residents slept under \u0027Hoover blankets\u0027 made of newspapers.","year":null,"difficulty":1,"aliases":["Hoovervilles","Shantytowns"],"key":["nov4"]},{"id":"b-077","kind":"event","topics":["economy","events"],"chapter":30,"page":736,"term":"Hoover Dam","def":"Colorado River project begun in 1930 and finished in 1936 that created Lake Mead.","detail":"Used for irrigation, flood control and electric power.","year":1936,"difficulty":2,"aliases":["Boulder Dam"]},{"id":"b-078","kind":"concept","topics":["economy","vocab"],"chapter":30,"page":736,"term":"Public works spending","def":"Trickle-down approach in which Congress appropriated $2.25 billion for large projects.","detail":"Hoover aided banks, railroads and rural credit corporations.","year":null,"difficulty":3,"aliases":[]},{"id":"b-079","kind":"concept","topics":["culture","vocab"],"chapter":30,"page":734,"term":"Brother, Can You Spare a Dime?","def":"Song that replaced \u0027My God, How the Money Rolls In\u0027 as the depression set in.","detail":"Symbolizes collapse of the cash-register era.","year":null,"difficulty":3,"aliases":[]},{"id":"b-080","kind":"concept","topics":["economy","vocab"],"chapter":30,"page":734,"term":"Bank failures","def":"Collapse of over 5,000 institutions in the first three years of depression, wiping out savings.","detail":"Many families lost homes and farms to foreclosure.","year":null,"difficulty":2,"aliases":["bank collapses"]},{"id":"b-081","kind":"concept","topics":["economy","vocab"],"chapter":30,"page":733,"term":"Early depression unemployment","def":"More than 4 million jobless by the end of 1930, tripling in two years.","detail":"Stocks did not regain 1929 levels until 1954.","year":1930,"difficulty":2,"aliases":["unemployment"]},{"id":"b-082","kind":"concept","topics":["economy","vocab"],"chapter":30,"page":733,"term":"Stock recovery to 1929 levels","def":"Year when stock values finally regained their pre-crash heights, a quarter-century later.","detail":"The crash heralded rather than caused the depression.","year":1954,"difficulty":3,"aliases":[]},{"id":"b-083","kind":"concept","topics":["economy","vocab"],"chapter":30,"page":736,"term":"Hoover\u0027s relief shift","def":"Reluctant abandonment of log-cabin individualism to aid banks, railroads and rural credit with federal money.","detail":"His spending paved the way for the New Deal.","year":null,"difficulty":2,"aliases":[]},{"id":"b-084","kind":"concept","topics":["economy","vocab"],"chapter":30,"page":722,"term":"Cash Register Chorus","def":"Cartoon image of businessmen singing while counting money, praising Coolidge\u0027s laissez-faire.","detail":"Titled \u0027What a Friend We Have in Coolidge!\u0027","year":null,"difficulty":3,"aliases":[]},{"id":"b-085","kind":"concept","topics":["economy","vocab"],"chapter":30,"page":731,"term":"Hoover as Commerce secretary","def":"Role in which he endorsed labor unions and supported federal regulation of radio broadcasting.","detail":"He flirted with a BBC-style government-owned radio.","year":null,"difficulty":3,"aliases":[]},{"id":"c-001","kind":"law","topics":["vocab","economy"],"chapter":30,"page":738,"term":"Reconstruction Finance Corporation","def":"Government lending bank created by Congress in 1932 to prop up banks, insurers, railroads and local governments, but not individuals.","detail":"Started with $500 million; critics called it the \u0027millionaires\u0027 dole\u0027 and a \u0027billion-dollar soup kitchen\u0027.","year":1932,"difficulty":1,"aliases":["RFC"],"key":["nov4"]},{"id":"c-002","kind":"law","topics":["vocab","economy"],"chapter":30,"page":738,"term":"Norris-La Guardia Anti-Injunction Act","def":"Law that barred federal courts from issuing injunctions against strikes, boycotts and peaceful picketing.","detail":"It also outlawed \u0027yellow-dog\u0027 contracts that forced workers to promise not to join unions.","year":1932,"difficulty":1,"aliases":["Norris-LaGuardia Act","Norris-La Guardia Act"],"key":["nov4"]},{"id":"c-003","kind":"term","topics":["vocab"],"chapter":30,"page":738,"term":"Yellow-dog contract","def":"Employer agreement requiring workers to promise never to join a union, outlawed in 1932.","detail":"Banned by the Norris-La Guardia Anti-Injunction Act.","year":1932,"difficulty":3,"aliases":["yellow dog contracts"]},{"id":"c-004","kind":"event","topics":["events","economy"],"chapter":30,"page":738,"term":"Bonus Army","def":"About 20,000 impoverished WWI veterans who marched on Washington in 1932 demanding early payment of a promised bonus.","detail":"Also called the Bonus Expeditionary Force; the bonus was approved in 1924 and payable in 1945.","year":1932,"difficulty":1,"aliases":["Bonus Expeditionary Force","BEF","Bonus March"],"key":["nov4"]},{"id":"c-005","kind":"term","topics":["vocab","economy"],"chapter":30,"page":738,"term":"Hoovervilles","def":"Shantytowns of the jobless and homeless named in mockery of the president, such as the veterans\u0027 camp in Washington.","detail":"The veterans built unsanitary shacks on vacant lots in the capital in 1932.","year":1932,"difficulty":2,"aliases":["Hooverville"]},{"id":"c-006","kind":"event","topics":["events"],"chapter":30,"page":739,"term":"Battle of Anacostia Flats","def":"Name for the 1932 clearing of the veterans\u0027 camp in Washington with bayonets and tear gas.","detail":"Shanties were burned and several veterans injured; an infant allegedly died from tear gas.","year":1932,"difficulty":2,"aliases":["Anacostia Flats"]},{"id":"c-007","kind":"person","topics":["people"],"chapter":30,"page":739,"term":"Douglas MacArthur","def":"Army general who evicted the Bonus Army with more force than Hoover had planned.","detail":"Franklin Roosevelt later named him one of the two most dangerous men in the country, along with Huey Long.","year":1932,"difficulty":2,"aliases":["MacArthur"]},{"id":"c-008","kind":"event","topics":["events"],"chapter":30,"page":739,"term":"Japanese invasion of Manchuria","def":"September 1931 seizure of a Chinese province by Japanese imperialists, closing the Open Door there.","detail":"A full-scale invasion of China followed in 1937; Japan set up puppet state Manchukuo in 1932.","year":1931,"difficulty":1,"aliases":["Manchurian Crisis","Manchuria"]},{"id":"c-009","kind":"term","topics":["vocab"],"chapter":30,"page":739,"term":"Stimson Doctrine","def":"1932 American policy refusing to recognize territorial changes gained by force, announced after Japan\u0027s seizure of Manchuria.","detail":"Critics said it was mere words; announced by Secretary of State Henry Stimson.","year":1932,"difficulty":1,"aliases":[],"key":["nov4"]},{"id":"c-010","kind":"person","topics":["people"],"chapter":30,"page":739,"term":"Henry L. Stimson","def":"Hoover\u0027s Secretary of State who announced non-recognition of territory taken by force.","detail":"His doctrine responded to the 1931 Japanese attack on Manchuria.","year":1932,"difficulty":2,"aliases":["Henry Stimson","Stimson"]},{"id":"c-011","kind":"term","topics":["vocab"],"chapter":30,"page":739,"term":"Manchukuo","def":"Puppet state Japan established in Manchuria in 1932.","detail":"It followed the 1931 invasion and violated treaties including the Kellogg Pact and Nine Power Treaty.","year":1932,"difficulty":2,"aliases":[]},{"id":"c-012","kind":"concept","topics":["vocab"],"chapter":30,"page":739,"term":"Collective security","def":"Idea of nations joining to stop aggressors, which died after the League failed to check Japan in Manchuria.","detail":"The US was not a League member and rejected economic pressure on Japan in 1931.","year":1931,"difficulty":2,"aliases":[]},{"id":"c-013","kind":"term","topics":["vocab"],"chapter":30,"page":739,"term":"League of Nations","def":"International body that could have blocked Japan but was weakened by lacking American membership.","detail":"League members had the power but lacked the courage to stop Japan.","year":1931,"difficulty":3,"aliases":[]},{"id":"c-014","kind":"concept","topics":["vocab"],"chapter":30,"page":740,"term":"Good Neighbor Policy","def":"Latin America approach begun by Hoover that softened US intervention, later expanded by Franklin Roosevelt.","detail":"Hoover\u0027s 1928 goodwill tour and Haiti withdrawal plan laid the foundation.","year":1932,"difficulty":1,"aliases":[]},{"id":"c-015","kind":"term","topics":["vocab"],"chapter":30,"page":740,"term":"Roosevelt Corollary","def":"Theodore Roosevelt\u0027s addition to the Monroe Doctrine that justified US intervention in Latin America, which Hoover tried to abandon.","detail":"Hoover\u0027s retreat from it helped soften imperial attitudes toward Latin neighbors.","year":null,"difficulty":2,"aliases":[]},{"id":"c-016","kind":"event","topics":["events"],"chapter":30,"page":740,"term":"Withdrawal from Haiti and Nicaragua","def":"Early-1930s end of long Marine occupations of two Caribbean nations under Hoover.","detail":"The Haiti withdrawal was set for 1934; the last Marines left Nicaragua in 1933 after about 20 years.","year":1933,"difficulty":3,"aliases":["Marines leave Nicaragua"]},{"id":"c-025","kind":"event","topics":["events","economy"],"chapter":30,"page":741,"term":"Stock market crash of 1929","def":"Collapse of share prices in 1929 that opened the Great Depression.","detail":"Called Black Tuesday in the chapter\u0027s key terms.","year":1929,"difficulty":1,"aliases":["Black Tuesday","Crash of 1929"]},{"id":"c-031","kind":"law","topics":["vocab","economy"],"chapter":30,"page":741,"term":"Capper-Volstead Act","def":"1921 law that aided farmers.","detail":"Passed the same year the Emergency Quota Act and Bureau of the Budget appeared.","year":1921,"difficulty":3,"aliases":[]},{"id":"c-033","kind":"event","topics":["events","culture"],"chapter":30,"page":741,"term":"Lindbergh\u0027s solo Atlantic flight","def":"1927 transatlantic flight made by one pilot.","detail":"Occurred the same year as the first talking film, The Jazz Singer.","year":1927,"difficulty":2,"aliases":["Charles Lindbergh"]},{"id":"c-034","kind":"event","topics":["events"],"chapter":30,"page":741,"term":"Execution of Sacco and Vanzetti","def":"1927 execution of two Italian-American anarchists after a 1921 trial.","detail":"Part of the Red Scare era.","year":1927,"difficulty":2,"aliases":["Sacco and Vanzetti"]},{"id":"c-036","kind":"person","topics":["people"],"chapter":31,"page":743,"term":"Franklin D. Roosevelt","def":"Democratic governor of New York elected president in 1932, fifth cousin of Theodore Roosevelt.","detail":"Won the electoral vote 472 to 59 over Hoover.","year":1932,"difficulty":1,"aliases":["FDR","Franklin Roosevelt"]},{"id":"c-037","kind":"concept","topics":["vocab","themes"],"chapter":31,"page":743,"term":"Polio","def":"Disease that struck Roosevelt in 1921 at age 39, leaving him with limited mobility.","detail":"He developed patience, compassion and willpower; press largely hid his wheelchair and ten-pound braces.","year":1921,"difficulty":2,"aliases":["infantile paralysis"]},{"id":"c-038","kind":"person","topics":["people"],"chapter":31,"page":743,"term":"Eleanor Roosevelt","def":"Active First Lady and \u0027conscience of the New Deal\u0027 who championed the poor and oppressed.","detail":"She defied segregation in Birmingham, Alabama, and wrote a syndicated newspaper column.","year":null,"difficulty":1,"aliases":["Eleanor"],"key":["nov4"]},{"id":"c-039","kind":"term","topics":["vocab"],"chapter":31,"page":744,"term":"Forgotten man","def":"Phrase from a 1932 Roosevelt speech for ordinary Americans overlooked by the economy.","detail":"Led wealthy critics to call him a \u0027traitor to his class\u0027.","year":1932,"difficulty":2,"aliases":["forgotten man speech"]},{"id":"c-040","kind":"concept","topics":["vocab","themes"],"chapter":31,"page":744,"term":"New Deal","def":"Roosevelt\u0027s pledge, made when accepting the 1932 nomination in person at Chicago, and name of his program.","detail":"He broke precedent by flying to the convention through storms to accept in person.","year":1932,"difficulty":1,"aliases":[],"key":["nov4"]},{"id":"c-042","kind":"term","topics":["vocab"],"chapter":31,"page":745,"term":"Brain Trust","def":"Small group of reform-minded young professors who ghostwrote FDR\u0027s speeches and drafted New Deal laws.","detail":"FDR\u0027s 1932 campaign promised a balanced budget despite later deficits.","year":1932,"difficulty":1,"aliases":[],"key":["nov4"]},{"id":"c-043","kind":"event","topics":["events"],"chapter":31,"page":745,"term":"Cermak assassination","def":"Feb. 15, 1933 attempt on Roosevelt in Florida that killed Chicago\u0027s mayor instead.","detail":"The victim was Mayor Anton Cermak.","year":1933,"difficulty":3,"aliases":["Assassination attempt on FDR"]},{"id":"c-044","kind":"event","topics":["events","economy"],"chapter":31,"page":746,"term":"Election of 1932","def":"Landslide in which Roosevelt defeated Hoover and ended a generation of Republican dominance.","detail":"Popular vote about 22.8 million to 15.8 million; electoral vote 472 to 59.","year":1932,"difficulty":1,"aliases":[]},{"id":"c-045","kind":"concept","topics":["vocab","themes"],"chapter":31,"page":746,"term":"Black shift to the Democrats","def":"Movement of African Americans away from the party of Lincoln during the Depression.","detail":"As \u0027last hired, first fired\u0027, they became a key part of the Democratic base in Northern cities.","year":1932,"difficulty":2,"aliases":[]},{"id":"c-046","kind":"concept","topics":["vocab"],"chapter":31,"page":746,"term":"Lame-duck period","def":"Months between Hoover\u0027s defeat and the March 4, 1933 inauguration, when banks closed and people hoarded money.","detail":"Roosevelt refused to commit to Hoover\u0027s anti-inflation plan: \u0027It\u0027s not my baby\u0027.","year":1933,"difficulty":3,"aliases":["lame duck"]},{"id":"c-047","kind":"concept","topics":["vocab","themes"],"chapter":31,"page":746,"term":"Three Rs","def":"Roosevelt\u0027s goals of relief, recovery and reform.","detail":"Short-range aims were relief and recovery; long-range reform of boom-or-bust abuses.","year":1933,"difficulty":1,"aliases":["Relief, Recovery, Reform"],"key":["nov4"]},{"id":"c-048","kind":"event","topics":["events"],"chapter":31,"page":746,"term":"Roosevelt\u0027s first inaugural address","def":"March 4, 1933 speech calling for war on the depression.","detail":"Said \u0027the only thing we have to fear is fear itself\u0027; denounced money changers.","year":1933,"difficulty":1,"aliases":["First Inaugural"]},{"id":"c-049","kind":"event","topics":["events","economy"],"chapter":31,"page":747,"term":"Hundred Days","def":"March 9 to June 16, 1933 special session of Congress that passed a flood of New Deal laws.","detail":"Preceded by Roosevelt\u0027s bank holiday of March 6-10.","year":1933,"difficulty":1,"aliases":["First Hundred Days"],"key":["nov4"]},{"id":"c-050","kind":"event","topics":["events","economy"],"chapter":31,"page":747,"term":"Bank holiday","def":"March 1933 nationwide closing of banks before they reopened on firmer footing.","detail":"Ran from March 6 to 10, 1933.","year":1933,"difficulty":2,"aliases":[]},{"id":"c-051","kind":"law","topics":["vocab","economy"],"chapter":31,"page":747,"term":"Emergency Banking Relief Act","def":"First Hundred Days law that let the president reopen solvent banks and regulate banking.","detail":"Passed in about eight hours and reached FDR unprinted.","year":1933,"difficulty":1,"aliases":["Emergency Banking Act"]},{"id":"c-052","kind":"event","topics":["events","economy"],"chapter":31,"page":748,"term":"Fireside chat","def":"Radio talks by FDR; the first reassured about 35 million listeners that banks were safe.","detail":"He said money was safer in a reopened bank than under the mattress.","year":1933,"difficulty":1,"aliases":["fireside chats"]},{"id":"c-053","kind":"law","topics":["vocab","economy"],"chapter":31,"page":748,"term":"Glass-Steagall Banking Reform Act","def":"1933 law that created deposit insurance and ended the bank-failure epidemic.","detail":"Insured deposits up to $5000; bank failures fell from 4004 in 1933 to 57 in 1934.","year":1933,"difficulty":1,"aliases":["Glass-Steagall Act"],"key":["nov4"]},{"id":"c-054","kind":"term","topics":["vocab","economy"],"chapter":31,"page":748,"term":"Federal Deposit Insurance Corporation","def":"Agency created in 1933 to insure individual bank deposits.","detail":"Initially insured up to $5000, ending wildcat bank failures dating to Andrew Jackson.","year":1933,"difficulty":1,"aliases":["FDIC"]},{"id":"c-055","kind":"concept","topics":["vocab","economy"],"chapter":31,"page":749,"term":"Managed currency","def":"Policy of manipulating money, via gold buying, to cause inflation and ease debtors\u0027 burdens.","detail":"Gold price raised from $21 an ounce in 1933 to $35 in early 1934.","year":1934,"difficulty":2,"aliases":[]},{"id":"c-056","kind":"event","topics":["events","economy"],"chapter":31,"page":749,"term":"Abandonment of the gold standard","def":"April 1933 order surrendering private gold and ending the gold standard at home.","detail":"Gold-payment clauses were canceled; critics mocked the \u0027baloney dollar\u0027.","year":1933,"difficulty":2,"aliases":["Off the gold standard"]},{"id":"c-057","kind":"concept","topics":["vocab","economy"],"chapter":31,"page":749,"term":"Pump priming","def":"Idea that federal spending would restart industrial recovery.","detail":"Applied to job creation when one in four workers was unemployed.","year":1933,"difficulty":2,"aliases":["Prime the pump"]},{"id":"c-058","kind":"term","topics":["vocab","economy"],"chapter":31,"page":749,"term":"Civilian Conservation Corps","def":"Probably the most popular New Deal program, putting young men in outdoor government camps.","detail":"Enrolled about 3 million; did reforestation and flood control; 47 died fighting fires.","year":1933,"difficulty":1,"aliases":["CCC"],"key":["nov4"]},{"id":"c-059","kind":"term","topics":["vocab","economy"],"chapter":31,"page":750,"term":"Federal Emergency Relief Administration","def":"First major relief agency, giving states about $3 billion for dole or work projects.","detail":"Run by Harry Hopkins; created in May 1933.","year":1933,"difficulty":1,"aliases":["FERA"]},{"id":"c-060","kind":"person","topics":["people"],"chapter":31,"page":750,"term":"Harry L. Hopkins","def":"New York social worker and Roosevelt adviser who ran FERA and the WPA.","detail":"Led relief efforts costing billions.","year":null,"difficulty":1,"aliases":["Harry Hopkins"]},{"id":"c-061","kind":"term","topics":["vocab","economy"],"chapter":31,"page":750,"term":"Home Owners\u0027 Loan Corporation","def":"New Deal agency that refinanced nonfarm home mortgages for about one million households.","detail":"Also won middle-class loyalty for the Democrats.","year":1933,"difficulty":2,"aliases":["HOLC"]},{"id":"c-062","kind":"term","topics":["vocab","economy"],"chapter":31,"page":750,"term":"Civil Works Administration","def":"Short-term jobs agency created by FDR in late 1933.","detail":"Established Nov. 9, 1933.","year":1933,"difficulty":3,"aliases":["CWA"]},{"id":"c-063","kind":"term","topics":["vocab"],"chapter":31,"page":750,"term":"Boondoggling","def":"Mocking term for make-work relief jobs such as leaf raking.","detail":"Joke: the only thing to fear is work itself.","year":1933,"difficulty":3,"aliases":["boondoggle"]},{"id":"c-064","kind":"term","topics":["vocab","economy"],"chapter":31,"page":747,"term":"Agricultural Adjustment Act","def":"May 1933 law aiming at recovery for farmers and giving mortgage help.","detail":"Passed May 12, 1933; a second version came in 1938.","year":1933,"difficulty":1,"aliases":["AAA"],"key":["nov4"]},{"id":"c-065","kind":"term","topics":["vocab","economy"],"chapter":31,"page":747,"term":"Tennessee Valley Authority","def":"Reform experiment created in May 1933 for a river valley.","detail":"Authorized by act of May 18, 1933.","year":1933,"difficulty":1,"aliases":["TVA"],"key":["nov5"]},{"id":"c-066","kind":"term","topics":["vocab","economy"],"chapter":31,"page":747,"term":"National Industrial Recovery Act","def":"June 1933 law creating the NRA and PWA.","detail":"Passed June 16, 1933 on the last day of the Hundred Days.","year":1933,"difficulty":1,"aliases":["NIRA"]},{"id":"c-067","kind":"term","topics":["vocab","economy"],"chapter":31,"page":747,"term":"National Recovery Administration","def":"Agency created under the 1933 industrial recovery act.","detail":"Created June 16, 1933 alongside the PWA.","year":1933,"difficulty":2,"aliases":["NRA"]},{"id":"c-068","kind":"term","topics":["vocab","economy"],"chapter":31,"page":747,"term":"Public Works Administration","def":"Agency created under the 1933 industrial recovery act for public construction.","detail":"Established June 16, 1933.","year":1933,"difficulty":2,"aliases":["PWA"]},{"id":"c-069","kind":"law","topics":["vocab","economy"],"chapter":31,"page":747,"term":"Federal Securities Act","def":"May 1933 reform measure regulating the sale of stocks.","detail":"Passed May 27, 1933.","year":1933,"difficulty":3,"aliases":[]},{"id":"c-070","kind":"law","topics":["vocab","economy"],"chapter":31,"page":751,"term":"Securities and Exchange Commission","def":"Agency authorized in 1934 to police Wall Street.","detail":"Authorized June 6, 1934 as a reform.","year":1934,"difficulty":2,"aliases":["SEC"]},{"id":"c-071","kind":"law","topics":["vocab","economy"],"chapter":31,"page":751,"term":"Gold Reserve Act","def":"1934 law authorizing FDR\u0027s devaluation of the dollar.","detail":"Passed Jan. 30, 1934.","year":1934,"difficulty":3,"aliases":[]},{"id":"c-072","kind":"law","topics":["vocab","economy"],"chapter":31,"page":756,"term":"Indian Reorganization Act","def":"1934 law, nicknamed the Indian New Deal, that restored tribal self-government, revived tribal culture, and stopped the loss of Indian lands.","detail":"Pushed by John Collier; critics called it another case of Washington deciding what was best for Indians.","year":1934,"difficulty":1,"aliases":["Indian New Deal"],"key":["nov5"]},{"id":"c-073","kind":"law","topics":["vocab","economy"],"chapter":31,"page":751,"term":"Reciprocal Trade Agreements Act","def":"1934 law aiding recovery through trade deals.","detail":"Passed June 12, 1934.","year":1934,"difficulty":3,"aliases":[]},{"id":"c-074","kind":"law","topics":["vocab","economy"],"chapter":31,"page":751,"term":"National Housing Act","def":"1934 law authorizing the Federal Housing Administration.","detail":"Passed June 28, 1934.","year":1934,"difficulty":2,"aliases":["FHA"]},{"id":"c-075","kind":"law","topics":["vocab","economy"],"chapter":31,"page":751,"term":"Works Progress Administration","def":"1935 agency run by Hopkins giving jobs on buildings, bridges and roads.","detail":"Spent about $11 billion; employed Steinbeck counting dogs.","year":1935,"difficulty":1,"aliases":["WPA"],"key":["nov4"]},{"id":"c-076","kind":"law","topics":["vocab","economy"],"chapter":31,"page":751,"term":"Wagner Act","def":"1935 labor law, also called the National Labor Relations Act.","detail":"Passed July 5, 1935.","year":1935,"difficulty":1,"aliases":["National Labor Relations Act","NLRA"],"key":["nov5"]},{"id":"c-077","kind":"law","topics":["vocab","economy"],"chapter":31,"page":751,"term":"Social Security Act","def":"1935 reform law establishing old-age insurance.","detail":"Passed Aug. 14, 1935.","year":1935,"difficulty":1,"aliases":[],"key":["nov5"]},{"id":"c-078","kind":"law","topics":["vocab","economy"],"chapter":31,"page":751,"term":"Fair Labor Standards Act","def":"1938 law, the Wages and Hours Bill.","detail":"Passed June 25, 1938.","year":1938,"difficulty":1,"aliases":["Wages and Hours Bill"],"key":["nov5"]},{"id":"c-079","kind":"law","topics":["vocab"],"chapter":31,"page":751,"term":"Hatch Act","def":"1939 reform law, last major measure in the table.","detail":"Passed Aug. 2, 1939.","year":1939,"difficulty":3,"aliases":[]},{"id":"c-080","kind":"person","topics":["people"],"chapter":31,"page":751,"term":"Father Charles Coughlin","def":"Michigan priest whose radio broadcasts attacked the New Deal and reached about 40 million.","detail":"His slogan was \u0027Social Justice\u0027; church superiors silenced him in 1942.","year":1930,"difficulty":1,"aliases":["Charles Coughlin","Father Coughlin"]},{"id":"c-081","kind":"person","topics":["people"],"chapter":31,"page":751,"term":"Francis E. Townsend","def":"Retired California physician who promised $200 a month to everyone over 60.","detail":"Part of the Depression demagogue movements.","year":null,"difficulty":2,"aliases":["Dr. Townsend","Townsend"]},{"id":"c-082","kind":"person","topics":["people"],"chapter":31,"page":751,"term":"Huey P. Long","def":"Louisiana senator called the Kingfish, whose Share Our Wealth plan promised \u0027Every Man a King\u0027.","detail":"Assassinated in the Louisiana capitol in 1935.","year":1935,"difficulty":1,"aliases":["Huey Long","Kingfish"]},{"id":"c-083","kind":"person","topics":["people"],"chapter":31,"page":751,"term":"Gerald L. K. Smith","def":"Long\u0027s lieutenant, called by Mencken the loudest and most dangerous orator.","detail":"Mencken said he was the gutsiest.","year":null,"difficulty":3,"aliases":["Gerald Smith"]},{"id":"c-084","kind":"concept","topics":["vocab","themes"],"chapter":31,"page":752,"term":"Share Our Wealth","def":"Plan promising every family $5000 taken from the prosperous.","detail":"Slogan was \u0027Every Man a King\u0027.","year":null,"difficulty":2,"aliases":[]},{"id":"c-085","kind":"event","topics":["events"],"chapter":31,"page":752,"term":"Assassination of Huey Long","def":"1935 killing of the Louisiana senator in the state capitol.","detail":"FDR had called him one of the two most dangerous men in the country.","year":1935,"difficulty":3,"aliases":[]},{"id":"c-086","kind":"term","topics":["vocab","culture"],"chapter":31,"page":752,"term":"Federal Art Project","def":"New Deal program that hired artists, producing murals like those at Coit Tower.","detail":"Victor Arnautoff painted The Pedestrian Scene in 1934.","year":1934,"difficulty":3,"aliases":[]},{"id":"d-001","kind":"person","topics":["people"],"chapter":31,"page":753,"term":"Father Coughlin","def":"Radio priest whose listeners flooded the Senate with telegrams and helped sink FDR\u0027s bid to join an international court.","detail":"His audience sent over 200,000 telegrams claiming moneyed international interests threatened American sovereignty (1935).","year":1935,"difficulty":2,"aliases":["Charles Coughlin","Charles E. Coughlin"]},{"id":"d-002","kind":"concept","topics":["vocab","events"],"chapter":31,"page":753,"term":"World Court treaty","def":"1935 proposal for U.S. membership in a judicial body tied to the League of Nations that the Senate refused to ratify.","detail":"Father Coughlin\u0027s radio campaign, with over 200,000 telegrams, is credited with defeating FDR\u0027s effort.","year":1935,"difficulty":3,"aliases":["World Court"]},{"id":"d-006","kind":"person","topics":["people"],"chapter":31,"page":753,"term":"Frances Perkins","def":"Roosevelt\u0027s Secretary of Labor and the first woman to serve in a presidential cabinet.","detail":"She was one of several women who gained visibility in the 1930s.","year":null,"difficulty":1,"aliases":[]},{"id":"d-007","kind":"person","topics":["people"],"chapter":31,"page":753,"term":"Mary McLeod Bethune","def":"Daughter of ex-slaves who founded a Florida college and became the highest-ranking African American in FDR\u0027s administration.","detail":"She directed minority affairs in the National Youth Administration and organized the \u0027Black Cabinet\u0027.","year":null,"difficulty":1,"aliases":["Bethune"]},{"id":"d-008","kind":"term","topics":["vocab","people"],"chapter":31,"page":753,"term":"Black Cabinet","def":"Informal group of African American advisers organized within the Roosevelt administration by an NYA official.","detail":"Mary McLeod Bethune organized it.","year":null,"difficulty":2,"aliases":[]},{"id":"d-009","kind":"term","topics":["vocab","people"],"chapter":31,"page":753,"term":"National Youth Administration","def":"New Deal agency in which an Office of Minority Affairs was directed by a prominent Black educator.","detail":"Mary McLeod Bethune led its Office of Minority Affairs.","year":null,"difficulty":3,"aliases":["NYA"]},{"id":"d-010","kind":"person","topics":["people","culture"],"chapter":31,"page":753,"term":"Ruth Benedict","def":"Anthropologist and student of Franz Boas who developed the \u0027culture and personality\u0027 school.","detail":"Her book Patterns of Culture (1934) treated cultures as collective personalities.","year":1934,"difficulty":2,"aliases":[]},{"id":"d-011","kind":"person","topics":["people","culture"],"chapter":31,"page":753,"term":"Margaret Mead","def":"Benedict\u0027s student who studied adolescence among Pacific islanders and explored sexuality, gender roles, and generations.","detail":"Working at the American Museum of Natural History, she achieved rare celebrity for a social scientist.","year":null,"difficulty":2,"aliases":[]},{"id":"d-012","kind":"term","topics":["vocab","culture"],"chapter":31,"page":753,"term":"Patterns of Culture","def":"1934 anthropological work portraying cultures as collective personalities.","detail":"Written by Ruth Benedict, who was a student of Franz Boas.","year":1934,"difficulty":3,"aliases":[]},{"id":"d-013","kind":"person","topics":["people","culture"],"chapter":31,"page":754,"term":"Pearl S. Buck","def":"Novelist raised in China by Presbyterian missionary parents who won the 1938 Nobel Prize for literature.","detail":"She was the third American Nobel literature laureate, after Sinclair Lewis and Eugene O\u0027Neill.","year":1938,"difficulty":2,"aliases":["Pearl Buck"]},{"id":"d-014","kind":"term","topics":["vocab","culture"],"chapter":31,"page":754,"term":"The Good Earth","def":"1931 novel that introduced American readers to Chinese peasant society.","detail":"Author Pearl S. Buck\u0027s pro-China writing later built American sympathy when Japan attacked China.","year":1931,"difficulty":2,"aliases":[]},{"id":"d-016","kind":"concept","topics":["vocab","economy"],"chapter":31,"page":754,"term":"Fair competition codes","def":"Industry-drafted rules setting shorter hours, minimum wages, and maximum hours to spread jobs among workers.","detail":"More than 200 industries were expected to adopt them under the NRA.","year":1933,"difficulty":2,"aliases":["industry codes"]},{"id":"d-017","kind":"concept","topics":["vocab","economy"],"chapter":31,"page":754,"term":"Blue eagle","def":"Symbol displayed by merchants to show participation in the New Deal\u0027s industrial recovery scheme.","detail":"Shops posted \u0027We Do Our Part\u0027 signs; Henry Ford called it \u0027that damn Roosevelt buzzard\u0027.","year":1933,"difficulty":2,"aliases":["blue eagle symbol"]},{"id":"d-018","kind":"concept","topics":["vocab","economy"],"chapter":31,"page":754,"term":"Yellow-dog contracts","def":"Antiunion agreements requiring workers to promise not to join unions, banned under the NRA.","detail":"The NRA also limited child labor and guaranteed collective bargaining.","year":1933,"difficulty":2,"aliases":["yellow dog contracts"]},{"id":"d-019","kind":"event","topics":["events","economy"],"chapter":31,"page":754,"term":"Schechter Poultry case","def":"Unanimous Supreme Court ruling that struck down the NRA, holding Congress cannot delegate legislative power and that commerce rules did not reach a local business.","detail":"The defendants were the Schechter brothers of Brooklyn; FDR denounced the Court\u0027s \u0027horse and buggy\u0027 view.","year":1935,"difficulty":1,"aliases":["Schechter v. United States","Schechter"]},{"id":"d-021","kind":"person","topics":["people"],"chapter":31,"page":754,"term":"Harold Ickes","def":"Blunt former \u0027bull mooser\u0027 and Secretary of the Interior who directed the public works program.","detail":"His agency spent over $4 billion on about 34,000 projects.","year":null,"difficulty":2,"aliases":["Harold L. Ickes"]},{"id":"d-022","kind":"event","topics":["events","economy"],"chapter":31,"page":755,"term":"Grand Coulee Dam","def":"Columbia River project in Washington that was the largest structure humans had built since the Great Wall of China.","detail":"It irrigates about half a million acres and generates more electricity than the TVA.","year":null,"difficulty":2,"aliases":["Grand Coulee"]},{"id":"d-023","kind":"law","topics":["vocab"],"chapter":31,"page":754,"term":"Beer legalization","def":"Hundred Days law permitting 3.2 percent beer and light wine, taxed at $5 per barrel.","detail":"Drys mocked Roosevelt as \u0027a 3.2 percent American\u0027; full repeal came with the Twenty-first Amendment.","year":1933,"difficulty":3,"aliases":["3.2 beer"]},{"id":"d-024","kind":"law","topics":["vocab"],"chapter":31,"page":754,"term":"Twenty-first Amendment","def":"1933 constitutional change that repealed Prohibition and reopened saloons.","detail":"It followed the Hundred Days legalization of 3.2 percent beer.","year":1933,"difficulty":2,"aliases":["21st Amendment"]},{"id":"d-025","kind":"term","topics":["vocab","economy"],"chapter":31,"page":755,"term":"Agricultural Adjustment Administration","def":"New Deal agency that paid farmers to reduce crop acreage in order to raise farm prices.","detail":"Funded by taxes on food processors; the Supreme Court struck it down in 1936.","year":1933,"difficulty":1,"aliases":["AAA"]},{"id":"d-026","kind":"concept","topics":["vocab","economy"],"chapter":31,"page":755,"term":"Parity prices","def":"Target farm prices giving growers the purchasing power they had in 1909-1914.","detail":"The AAA tried to achieve them through \u0027artificial scarcity\u0027.","year":null,"difficulty":2,"aliases":["parity"]},{"id":"d-027","kind":"concept","topics":["vocab","economy"],"chapter":31,"page":755,"term":"Plow-under program","def":"Wasteful AAA policy of destroying young cotton plants and buying and slaughtering millions of pigs to cut supply.","detail":"It started late in 1933, after much cotton was planted, and angered critics while people were hungry.","year":1933,"difficulty":2,"aliases":["subsidized scarcity","artificial scarcity"]},{"id":"d-028","kind":"concept","topics":["vocab","economy"],"chapter":31,"page":755,"term":"Processing tax","def":"Levy on food processors such as flour millers that funded AAA payments and was passed to consumers.","detail":"The Supreme Court declared it unconstitutional in 1936, ending the original AAA.","year":1936,"difficulty":2,"aliases":[]},{"id":"d-029","kind":"law","topics":["vocab","economy"],"chapter":31,"page":756,"term":"Soil Conservation and Domestic Allotment Act","def":"1936 farm law, with a second AAA in 1938, that permanently transformed agriculture into a heavily subsidized industry.","detail":"It turned independent yeoman farmers into recipients of government subsidies.","year":1936,"difficulty":3,"aliases":["Soil Conservation Act"]},{"id":"d-030","kind":"event","topics":["events","economy"],"chapter":31,"page":756,"term":"Dust Bowl","def":"Region of the Great Plains, from eastern Colorado to western Missouri, where drought and blowing topsoil began in late 1933.","detail":"Mechanized tractors and disk plows had torn up sod; dust blew as far as New York.","year":1933,"difficulty":1,"aliases":["Dust Bowl drought","black blizzards"],"key":["nov4","nov5"]},{"id":"d-031","kind":"concept","topics":["vocab","economy"],"chapter":31,"page":756,"term":"Okies","def":"Nickname for Oklahomans, along with Arkansans (\u0027Arkies\u0027), who fled to California in junkyard-car caravans.","detail":"About 350,000 migrated, many finding work in the San Joaquin Valley and facing \u0027KEEP OUT\u0027 hostility.","year":null,"difficulty":1,"aliases":["Arkies","Okies and Arkies"]},{"id":"d-032","kind":"person","topics":["people","culture"],"chapter":31,"page":756,"term":"John Steinbeck","def":"Novelist whose 1939 book portrayed the Dust Bowl migrant experience.","detail":"His The Grapes of Wrath was called the \u0027Uncle Tom\u0027s Cabin\u0027 of the Dust Bowl.","year":1939,"difficulty":1,"aliases":[]},{"id":"d-033","kind":"term","topics":["vocab","culture"],"chapter":31,"page":756,"term":"The Grapes of Wrath","def":"1939 novel following migrant farm families from the Dust Bowl to California.","detail":"Steinbeck\u0027s Joads traveled Route 66 to California.","year":1939,"difficulty":1,"aliases":[]},{"id":"d-034","kind":"term","topics":["vocab","economy"],"chapter":31,"page":756,"term":"Resettlement Administration","def":"1935 agency that moved families with little or no farmland onto better land.","detail":"It was one New Deal response to Dust Bowl devastation.","year":1935,"difficulty":2,"aliases":[]},{"id":"d-036","kind":"person","topics":["people"],"chapter":31,"page":756,"term":"John Collier","def":"Commissioner of Indian Affairs who rejected forced assimilation and pushed to restore tribal autonomy.","detail":"He opposed the approach of the 1887 Dawes Act.","year":null,"difficulty":2,"aliases":[]},{"id":"d-038","kind":"concept","topics":["vocab"],"chapter":31,"page":757,"term":"Navajo opposition","def":"Largest group among 77 tribes that refused to organize under the 1934 Indian law, angered over lost grazing lands.","detail":"They resented white stockmen taking grazing land.","year":1934,"difficulty":3,"aliases":["Dine","Navajo"]},{"id":"d-039","kind":"law","topics":["vocab","economy"],"chapter":31,"page":757,"term":"Truth in Securities Act","def":"Hundred Days law requiring promoters to give investors independently audited information.","detail":"It shifted the motto from \u0027let the seller beware\u0027 to \u0027let the buyer beware\u0027.","year":1933,"difficulty":2,"aliases":["Federal Securities Act"]},{"id":"d-041","kind":"law","topics":["vocab","economy"],"chapter":31,"page":757,"term":"Public Utility Holding Company Act","def":"1935 law that gave huge multilayered utility empires a \u0027death sentence\u0027 except where economically needed.","detail":"Critics said holding companies let a \u0027four-inch tail\u0027 wag a \u0027ninety-six-inch dog\u0027.","year":1935,"difficulty":2,"aliases":["Holding Company Act"]},{"id":"d-042","kind":"person","topics":["people","economy"],"chapter":31,"page":757,"term":"Samuel Insull","def":"Chicago utility magnate whose holding-company empire collapsed in 1932.","detail":"His fall became an example of abuse by public utility holding companies.","year":1932,"difficulty":3,"aliases":[]},{"id":"d-044","kind":"person","topics":["people"],"chapter":31,"page":758,"term":"George W. Norris","def":"Nebraska senator who championed the Tennessee Valley project, and for whom one of its dams was named.","detail":"He backed public development of Muscle Shoals-area power.","year":null,"difficulty":2,"aliases":["George Norris"]},{"id":"d-045","kind":"concept","topics":["vocab","economy"],"chapter":31,"page":758,"term":"Muscle Shoals","def":"Government-owned plants built to make nitrates in World War I that became part of the Tennessee Valley scheme.","detail":"The Tennessee valley drained an area the size of England holding about 2.5 million poor people.","year":null,"difficulty":3,"aliases":[]},{"id":"d-046","kind":"concept","topics":["vocab","economy"],"chapter":31,"page":758,"term":"Yardstick principle","def":"Idea that public power would measure the fairness of rates charged by private utilities.","detail":"Utilities replied that cheap public power came from dishonest bookkeeping and no taxes.","year":null,"difficulty":3,"aliases":["yardstick"]},{"id":"d-047","kind":"term","topics":["vocab","economy"],"chapter":31,"page":758,"term":"Federal Housing Administration","def":"1934 agency offering small loans for home repairs and new homes, one of few alphabet agencies to outlive Roosevelt.","detail":"It was set up in 1934.","year":1934,"difficulty":2,"aliases":["FHA"]},{"id":"d-048","kind":"term","topics":["vocab","economy"],"chapter":31,"page":758,"term":"United States Housing Authority","def":"1937 agency lending to states and communities for low-cost housing, starting about 650,000 units.","detail":"Despite this, it fell short of the need and slum areas stopped growing for the first time in a century.","year":1937,"difficulty":2,"aliases":["USHA"]},{"id":"d-050","kind":"concept","topics":["vocab","economy"],"chapter":31,"page":759,"term":"Payroll tax","def":"Levy on both employers and employees that financed the 1935 retirement and unemployment system.","detail":"It later cut into workers\u0027 incomes before the 1937 downturn.","year":1935,"difficulty":3,"aliases":[]},{"id":"d-052","kind":"event","topics":["events","economy"],"chapter":31,"page":759,"term":"San Francisco general strike","def":"1934 \u0027Bloody Thursday\u0027 labor action broken by vigilante citizens.","detail":"Strikes rose in 1934 as labor felt more secure.","year":1934,"difficulty":3,"aliases":["Bloody Thursday"]},{"id":"d-054","kind":"person","topics":["people"],"chapter":31,"page":760,"term":"Robert F. Wagner","def":"New York senator for whom the 1935 labor-rights law is named.","detail":"His law created the NLRB.","year":1935,"difficulty":2,"aliases":["Robert Wagner"]},{"id":"d-055","kind":"term","topics":["vocab","economy"],"chapter":31,"page":760,"term":"National Labor Relations Board","def":"Agency created to protect workers\u0027 right to organize and bargain through chosen representatives.","detail":"Under it, unskilled workers began organizing into unions.","year":1935,"difficulty":2,"aliases":["NLRB"]},{"id":"d-056","kind":"person","topics":["people","economy"],"chapter":31,"page":760,"term":"John L. Lewis","def":"Domineering United Mine Workers boss who led the push to organize unskilled industrial workers.","detail":"He formed the Committee for Industrial Organization in 1935 inside the AF of L.","year":1935,"difficulty":1,"aliases":[]},{"id":"d-057","kind":"term","topics":["vocab","economy"],"chapter":31,"page":760,"term":"Congress of Industrial Organizations","def":"Labor federation for unskilled industrial workers that broke with the AF of L in 1938.","detail":"By 1940 it had about 4 million members, including about 200,000 Black workers.","year":1938,"difficulty":1,"aliases":["CIO","Committee for Industrial Organization"]},{"id":"d-058","kind":"term","topics":["vocab","economy"],"chapter":31,"page":760,"term":"American Federation of Labor","def":"Craft-oriented union federation that long favored skilled workers and suspended CIO-linked unions in 1936.","detail":"It was unsympathetic to unskilled and especially Black workers.","year":null,"difficulty":2,"aliases":["AF of L","AFL"]},{"id":"d-059","kind":"concept","topics":["vocab","economy"],"chapter":31,"page":760,"term":"Sit-down strike","def":"Tactic in which workers refuse to leave the factory, preventing strikebreakers from entering.","detail":"Used at General Motors in Flint, Michigan, 1936-1937.","year":1936,"difficulty":1,"aliases":["sit-down strikes"]},{"id":"d-060","kind":"event","topics":["events","economy"],"chapter":31,"page":760,"term":"Flint GM strike","def":"1936-1937 sit-down strike that won the United Auto Workers recognition as sole bargaining agent for a car giant.","detail":"U.S. Steel voluntarily accepted unionization to avoid a costly strike.","year":1937,"difficulty":1,"aliases":["General Motors strike","Flint sit-down strike"]},{"id":"d-061","kind":"event","topics":["events","economy"],"chapter":31,"page":761,"term":"Memorial Day massacre","def":"1937 incident at a Republic Steel plant in South Chicago when police fired on pickets, killing and wounding workers.","detail":"It illustrated the violent resistance by \u0027Little Steel\u0027 companies.","year":1937,"difficulty":2,"aliases":["Memorial Day Massacre"]},{"id":"d-063","kind":"person","topics":["people"],"chapter":31,"page":762,"term":"Alfred Landon","def":"Moderate Kansas governor, the colorless but honest Republican nominee against FDR in 1936.","detail":"He carried only Maine and Vermont.","year":1936,"difficulty":1,"aliases":["Alf Landon","Alfred M. Landon"]},{"id":"d-064","kind":"event","topics":["events"],"chapter":31,"page":762,"term":"Election of 1936","def":"Landslide in which FDR won 523 electoral votes to 8, the most lopsided in 116 years.","detail":"Popular vote was 27,752,869 to 16,674,665.","year":1936,"difficulty":1,"aliases":["1936 election"]},{"id":"d-065","kind":"concept","topics":["vocab"],"chapter":31,"page":762,"term":"American Liberty League","def":"Group of wealthy conservatives organized in 1934 to fight the \u0027socialistic\u0027 New Deal.","detail":"Hoover\u0027s rhetoric echoed its views in 1936.","year":1934,"difficulty":2,"aliases":[]},{"id":"d-066","kind":"concept","topics":["vocab"],"chapter":31,"page":762,"term":"Economic royalists","def":"FDR\u0027s label for wealthy opponents who hid behind the Constitution while attacking his reforms.","detail":"He used the attack on the stump in 1936.","year":1936,"difficulty":3,"aliases":[]},{"id":"d-067","kind":"concept","topics":["vocab","themes"],"chapter":31,"page":762,"term":"New Deal coalition","def":"Powerful Democratic alliance of Southerners, Blacks, urbanites, and the poor, especially new immigrants, built by FDR.","detail":"It dominated American politics for nearly four decades after 1932.","year":1936,"difficulty":1,"aliases":["Roosevelt coalition"]},{"id":"d-069","kind":"law","topics":["vocab"],"chapter":31,"page":762,"term":"Twentieth Amendment","def":"Ratified in 1933, it ended lame-duck sessions and moved the inauguration from March 4 to January 20.","detail":"It shortened the gap between election and inauguration by six weeks.","year":1933,"difficulty":2,"aliases":["20th Amendment","Lame Duck Amendment"]},{"id":"d-070","kind":"event","topics":["events"],"chapter":31,"page":763,"term":"Court-packing plan","def":"FDR\u0027s early 1937 proposal to add justices, up to fifteen, to a Supreme Court blocking the New Deal.","detail":"Congress passed only a watered-down bill for lower courts, FDR\u0027s first major legislative defeat.","year":1937,"difficulty":1,"aliases":["court packing","Judiciary Reorganization"],"key":["nov5"]},{"id":"d-071","kind":"person","topics":["people"],"chapter":31,"page":763,"term":"Owen J. Roberts","def":"Justice whose shift toward liberal colleagues in 1937 produced the \u0027switch in time that saved nine\u0027.","detail":"A 5-4 decision upheld a state minimum wage for women, reversing a case from a year earlier.","year":1937,"difficulty":2,"aliases":["Justice Roberts","Owen Roberts"]},{"id":"d-072","kind":"concept","topics":["vocab"],"chapter":31,"page":763,"term":"Switch in time that saved nine","def":"Quip about the Court\u0027s 1937 turn toward upholding New Deal laws, which undercut support for expansion.","detail":"The Court then upheld the Wagner Act and Social Security Act.","year":1937,"difficulty":2,"aliases":[]},{"id":"d-073","kind":"event","topics":["events","economy"],"chapter":31,"page":764,"term":"Roosevelt recession","def":"Sharp second downturn of 1937 blamed on payroll taxes and spending cuts to balance the budget.","detail":"Unemployment was about 15% in 1936, down from 25% in 1933.","year":1937,"difficulty":1,"aliases":["recession of 1937"]},{"id":"d-074","kind":"concept","topics":["vocab","economy"],"chapter":31,"page":764,"term":"Keynesianism","def":"Economic approach using government deficit spending and fiscal policy to prime the pump and boost consumer spending.","detail":"FDR embraced John Maynard Keynes in April 1937 and it became orthodoxy for decades.","year":1937,"difficulty":1,"aliases":["Keynesian economics"]},{"id":"d-075","kind":"law","topics":["vocab"],"chapter":31,"page":764,"term":"Reorganization Act","def":"1939 law that was the first major overhaul of the executive branch since Washington.","detail":"It created the Executive Office of the President.","year":1939,"difficulty":2,"aliases":["Reorganization Act of 1939"]},{"id":"d-077","kind":"concept","topics":["vocab","themes"],"chapter":31,"page":764,"term":"One-third of a nation","def":"Phrase from FDR\u0027s 1937 second inaugural describing Americans ill-housed, ill-clad, and ill-nourished.","detail":"He said progress is measured by providing for those who have too little.","year":1937,"difficulty":2,"aliases":["ill-housed, ill-clad, ill-nourished"]},{"id":"d-078","kind":"event","topics":["events"],"chapter":31,"page":765,"term":"Election of 1938","def":"Midterm in which Republicans cut heavily into New Deal majorities for the first time without winning either house.","detail":"FDR\u0027s attempted \u0027purge\u0027 of Democratic opponents failed; all three senators he opposed were reelected.","year":1938,"difficulty":2,"aliases":["1938 midterms","purge of 1938"]},{"id":"d-079","kind":"concept","topics":["vocab","themes"],"chapter":31,"page":765,"term":"Handout state","def":"Business criticism that the New Deal undermined thrift and initiative, replacing self-reliance with \u0027gimmies\u0027.","detail":"Federal debt rose from $19.5 billion in 1932 to $40.4 billion in 1939.","year":null,"difficulty":2,"aliases":["gimmies"]},{"id":"d-080","kind":"concept","topics":["vocab","economy"],"chapter":31,"page":765,"term":"National debt growth","def":"Federal debt that rose from about $19.5 billion in 1932 to $40.4 billion in 1939.","detail":"Defenders note it hit $258 billion in 1945 due mainly to WWII.","year":1939,"difficulty":2,"aliases":["national debt"]},{"id":"d-081","kind":"concept","topics":["vocab","themes"],"chapter":31,"page":767,"term":"Balancing the human budget","def":"Defenders\u0027 idea that the government must prevent mass hunger even if the federal budget goes unbalanced.","detail":"They said FDR saved capitalism from its worst abuses without bloody revolution.","year":null,"difficulty":2,"aliases":[]},{"id":"d-082","kind":"concept","topics":["vocab","themes"],"chapter":31,"page":767,"term":"New Deal radicalism debate","def":"Historians\u0027 dispute over whether the New Deal was revolutionary or conservative, including Degler\u0027s \u0027revolutionary response\u0027 view.","detail":"Schlesinger saw reform cycles; Barton Bernstein from the left said it did not go far enough.","year":null,"difficulty":3,"aliases":["Carl Degler","Barton Bernstein","Arthur Schlesinger"]},{"id":"d-083","kind":"concept","topics":["vocab","themes"],"chapter":31,"page":768,"term":"Constraints school","def":"1970s-1990s historians who argued the New Deal offered as much reform as circumstances and public opinion allowed.","detail":"Includes James Patterson, Alan Brinkley, Kenneth Jackson, Harvard Sitkoff, and Lizabeth Cohen.","year":null,"difficulty":2,"aliases":["constraints historians"]},{"id":"d-084","kind":"person","topics":["people","themes"],"chapter":31,"page":768,"term":"William Leuchtenburg","def":"Historian who called the New Deal a \u0027half-way revolution\u0027.","detail":"He saw it as neither radical nor conservative.","year":null,"difficulty":3,"aliases":["Leuchtenburg"]},{"id":"d-085","kind":"person","topics":["people","themes"],"chapter":31,"page":768,"term":"Ira Katznelson","def":"Scholar arguing that southern Democrats in Congress shaped and constrained the New Deal along racial lines.","detail":"Kessler-Harris, Gordon, and Mettler instead stressed gender bias favoring male breadwinners.","year":null,"difficulty":3,"aliases":[]},{"id":"e-001","kind":"term","topics":["vocab","economy"],"chapter":30,"page":707,"term":"Airmail","def":"Government mail contracts that let private companies run early passenger air lines, in effect a federal subsidy for aviation.","detail":"The first transcontinental route ran from New York to San Francisco in 1920.","year":1920,"difficulty":1,"aliases":["Air mail"],"key":["oct28"]},{"id":"e-002","kind":"term","topics":["vocab","culture"],"chapter":30,"page":710,"term":"Spectator sports","def":"Industry that became big business in the 1920s, turning athletes like Babe Ruth and Jack Dempsey into media-made celebrities.","detail":"Dempsey\u0027s 1921 bout with Georges Carpentier drew the first of the decade\u0027s million-dollar gates.","year":null,"difficulty":1,"aliases":["Sports"],"key":["oct28"]},{"id":"e-003","kind":"term","topics":["vocab","events"],"chapter":30,"page":712,"term":"Bolsheviks","def":"Russian communist revolutionaries whose 1917 seizure of power fed American fear of radicals after World War I.","detail":"Many Americans blamed postwar strikes on \"bomb-and-whisker\" radicals; a tiny U.S. Communist party formed.","year":1917,"difficulty":1,"aliases":["Bolshevik","Bolshevik Revolution"],"key":["oct28"]},{"id":"e-004","kind":"term","topics":["vocab","culture"],"chapter":30,"page":718,"term":"Bible Belt","def":"Nickname for the heavily religious South, where several states banned teaching evolution in public schools.","detail":"A stronghold of fundamentalism and of the nativist KKK, it rejected the Catholic, \"wet\" Al Smith in 1928.","year":null,"difficulty":1,"aliases":[],"key":["oct28"]},{"id":"e-005","kind":"term","topics":["vocab","culture"],"chapter":30,"page":720,"term":"Expatriates","def":"Americans living abroad, like the Lost Generation writers and painters who settled in postwar Europe.","detail":"Hemingway\u0027s The Sun Also Rises (1926) portrays a group of these disillusioned Americans.","year":null,"difficulty":1,"aliases":["Expatriate"],"key":["nov2"]},{"id":"e-006","kind":"person","topics":["people","economy"],"chapter":31,"page":764,"term":"John Maynard Keynes","def":"British economist whose ideas FDR finally embraced in 1937, calling for planned government deficits to stimulate the economy.","detail":"His approach (Keynesianism) became economic orthodoxy for decades.","year":1937,"difficulty":1,"aliases":["Keynes"],"key":["nov5"]},{"id":"e-007","kind":"concept","topics":["vocab","economy","themes"],"chapter":31,"page":764,"term":"Deficit spending","def":"Government deliberately spending more than it collects in taxes to prime the pump and boost demand.","detail":"The New Deal ran about $20 billion in deficits over six years; many economists said bigger deficits would have worked better.","year":null,"difficulty":1,"aliases":["Deficit"],"key":["nov5"]}],"causeEffect":[{"id":"a-ce-01","chapter":30,"cause":"Henry Ford adopted the moving assembly line and high wages","effect":"Cars became cheap enough for ordinary families, with a Model T falling to about two months of wages by 1924","why":"Mass production cut costs and widened the market.","difficulty":1},{"id":"a-ce-02","chapter":30,"cause":"Mass car ownership spread across the 1920s","effect":"Suburbs grew, commuting began, and oil, rubber, and highway industries boomed","why":"The auto reorganized work and residence and created supporting industries.","difficulty":1},{"id":"a-ce-03","chapter":30,"cause":"Radio networks and talking movies reached huge audiences","effect":"Regional differences and ethnic divides softened as tastes and accents standardized","why":"Shared media created a more unified national culture.","difficulty":2},{"id":"a-ce-04","chapter":30,"cause":"Manufacturers solved production problems and needed mass markets","effect":"Advertising and installment buying exploded, building a cloud of consumer debt","why":"Selling more goods meant persuading and financing consumers.","difficulty":1},{"id":"a-ce-05","chapter":30,"cause":"Fear of Bolshevism and postwar strikes","effect":"The Red Scare brought Palmer raids, deportations, and criminal syndicalism laws","why":"Anxiety about radicals led to government crackdowns.","difficulty":1},{"id":"a-ce-06","chapter":30,"cause":"Nativism and fear of the New Immigration","effect":"Congress passed the Immigration Act of 1924 with national-origin quotas","why":"Restrictionists wanted to favor northern Europeans.","difficulty":1},{"id":"a-ce-07","chapter":30,"cause":"Prohibition made alcohol illegal while demand remained","effect":"Speakeasies, bootlegging, and violent gangs like Capone\u0027s flourished","why":"Illegal profits funded organized crime.","difficulty":1},{"id":"a-ce-08","chapter":30,"cause":"Fundamentalists feared evolution undermined faith and morals","effect":"Tennessee prosecuted John Scopes in the 1925 Monkey Trial","why":"State law banned teaching evolution.","difficulty":2},{"id":"a-ce-09","chapter":30,"cause":"Klan officials embezzled money and terrorism repelled decent people","effect":"The Klan collapsed in the late 1920s","why":"Scandal and revulsion drained membership.","difficulty":3},{"id":"a-ce-10","chapter":30,"cause":"Black migration north during and after WWI","effect":"Harlem became a center of creative culture and race pride, including Garvey\u0027s UNIA","why":"Concentrated Black communities nurtured art and politics.","difficulty":2},{"id":"b-ce-01","chapter":30,"cause":"Mellon\u0027s large tax cuts favoring the wealthy","effect":"Tax burden shifted toward middle-income groups while the national debt fell by $10 billion","why":"Cuts reduced the rates on high incomes, so others carried relatively more of the load.","difficulty":2},{"id":"b-ce-02","chapter":30,"cause":"Albert Fall secretly leased naval oil reserves to Sinclair and Doheny","effect":"Teapot Dome scandal, with Fall convicted of bribery","why":"Fall accepted bribes for the leases, which leaked in 1923 and led to indictments.","difficulty":1},{"id":"b-ce-03","chapter":30,"cause":"Mechanized tractors and expanded wartime acreage","effect":"Crop surpluses and falling farm prices","why":"More output per farmer pushed prices down, driving farm debt.","difficulty":2},{"id":"b-ce-04","chapter":30,"cause":"Falling farm prices and the farm bloc\u0027s pressure","effect":"McNary-Haugen Bill passed twice and vetoed twice by Coolidge","why":"Farmers sought price support, but Coolidge refused government surplus purchases.","difficulty":2},{"id":"b-ce-05","chapter":30,"cause":"Democratic party splits over wets, drys, and the Klan","effect":"102-ballot deadlock and the nomination of John W. Davis","why":"Divided factions could not agree, so a compromise conservative emerged.","difficulty":3},{"id":"b-ce-06","chapter":30,"cause":"US insistence on war debt repayment plus high Fordney-McCumber tariffs","effect":"Europeans struggled to earn dollars and relied on American loans like the Dawes Plan","why":"Tariffs blocked European exports, so debts could only be paid through borrowing.","difficulty":1},{"id":"b-ce-07","chapter":30,"cause":"Al Smith\u0027s Catholicism, wet stance and weak radio presence","effect":"Hoover won the 1928 landslide, 444 to 87, cracking the Solid South","why":"Religious bigotry and prohibition views cost Smith votes, while Hoover\u0027s voice suited radio.","difficulty":2},{"id":"b-ce-08","chapter":30,"cause":"Britain raised interest rates and speculators dumped shares","effect":"Black Tuesday crash of October 29, 1929","why":"Capital flowed home and selling panic erupted in an overextended bubble.","difficulty":1},{"id":"b-ce-09","chapter":30,"cause":"Hawley-Smoot Tariff raised duties to about 60 percent","effect":"Foreign retaliation and deeper global depression","why":"Higher barriers choked world trade and forced nations into economic isolation.","difficulty":1},{"id":"b-ce-10","chapter":30,"cause":"Federal Reserve held interest rates high after the crash","effect":"Money supply tightened and recovery was delayed","why":"Costly borrowing turned a stock crash into a deeper financial crisis.","difficulty":2},{"id":"c-ce-01","chapter":30,"cause":"Hoover asked Congress for help late in 1932 and the RFC was created.","effect":"Government loans propped up banks and railroads but arrived months too late to be most useful.","why":"Emergency lending helped businesses yet came after the crisis had deepened.","difficulty":2},{"id":"c-ce-02","chapter":30,"cause":"Veterans marched on Washington demanding early bonus payment in 1932.","effect":"MacArthur\u0027s troops cleared the camps with tear gas and bayonets, turning opinion against Hoover.","why":"The harsh eviction made Hoover appear heartless.","difficulty":1},{"id":"c-ce-03","chapter":30,"cause":"Japan invaded Manchuria in 1931.","effect":"The US issued the Stimson Doctrine refusing to recognize gains by force.","why":"With no League membership or sanctions, America offered only non-recognition.","difficulty":1},{"id":"c-ce-04","chapter":30,"cause":"The Depression weakened American investments abroad.","effect":"Economic imperialism became less popular and Hoover laid the Good Neighbor Policy foundation.","why":"Fewer dollars and goodwill efforts softened aggressive Latin America policy.","difficulty":2},{"id":"c-ce-05","chapter":30,"cause":"Congress passed the Norris-La Guardia Act in 1932.","effect":"Federal courts could no longer enjoin strikes or peaceful picketing, and yellow-dog contracts ended.","why":"The law shifted legal power toward unions.","difficulty":3},{"id":"c-ce-06","chapter":31,"cause":"Roosevelt overcame polio and paralysis.","effect":"He developed patience and compassion that made him a more effective, empathetic leader.","why":"His illness humbled the once lightweight politician.","difficulty":3},{"id":"c-ce-07","chapter":31,"cause":"Hoover\u0027s depression produced mass unemployment of over 11 million by 1932.","effect":"Voters elected Roosevelt 472 to 59 in a landslide.","why":"Anger over the Depression swept Hoover and Republicans out.","difficulty":1},{"id":"c-ce-08","chapter":31,"cause":"Banks failed and people hoarded money before the inauguration.","effect":"Roosevelt declared a bank holiday and passed the Emergency Banking Relief Act.","why":"Closing and reopening banks restored confidence.","difficulty":1},{"id":"c-ce-09","chapter":31,"cause":"Roosevelt\u0027s fireside chat told listeners their deposits were safe.","effect":"Confidence returned and banks reopened.","why":"Calm, direct reassurance reversed panic.","difficulty":2},{"id":"c-ce-10","chapter":31,"cause":"Glass-Steagall created the FDIC in 1933.","effect":"Bank failures dropped from 4004 in 1933 to 57 in 1934.","why":"Insured deposits removed the reason for runs on banks.","difficulty":1},{"id":"c-ce-11","chapter":31,"cause":"The government raised the price of gold and left the gold standard.","effect":"Inflation increased money in circulation, easing debts but angering sound-money critics.","why":"Managed currency aimed to raise prices.","difficulty":2},{"id":"c-ce-12","chapter":31,"cause":"One in four workers was jobless at FDR\u0027s inauguration.","effect":"Congress created the CCC, FERA and later the WPA.","why":"Federal job and relief programs aimed to prime the pump.","difficulty":1},{"id":"c-ce-13","chapter":31,"cause":"Persistent unemployment after emergency relief in 1934.","effect":"Demagogues like Coughlin, Townsend and Long gained followers.","why":"Economic desperation made radical promises attractive.","difficulty":2},{"id":"d-ce-01","chapter":31,"cause":"The Supreme Court ruled in Schechter Poultry that Congress could not delegate legislative power and that commerce rules did not cover local business.","effect":"The NRA and its blue eagle codes were struck down, leaving labor without protection.","why":"Losing NRA guarantees of collective bargaining led Congress to pass the Wagner Act.","difficulty":1},{"id":"d-ce-02","chapter":31,"cause":"The NLRB protected the right to organize, and the AF of L neglected unskilled workers.","effect":"John L. Lewis formed the CIO, which organized unskilled industrial workers and broke with the AF of L.","why":"Federal protection made mass organizing in factories possible, and craft unions refused to do it.","difficulty":1},{"id":"d-ce-03","chapter":31,"cause":"The AAA paid farmers to cut acreage and destroy crops during widespread hunger.","effect":"Critics attacked wasteful destruction, and the Supreme Court struck down the processing tax in 1936.","why":"The program raised farm income but angered consumers, processors, and taxpayers, and the Court found the tax unconstitutional.","difficulty":2},{"id":"d-ce-04","chapter":31,"cause":"Farmers plowed up marginal prairie with tractors and disk plows, then drought hit in late 1933.","effect":"Topsoil blew away in the Dust Bowl and about 350,000 Okies migrated to California.","why":"Stripped sod had no protection against drought and wind.","difficulty":1},{"id":"d-ce-05","chapter":31,"cause":"Sit-down strikes at General Motors in Flint kept strikebreakers out of the plants.","effect":"The UAW won recognition as GM\u0027s sole bargaining agent in 1937, and U.S. Steel unionized voluntarily.","why":"Occupying plants gave workers leverage and showed industrial unionism could succeed.","difficulty":2},{"id":"d-ce-06","chapter":31,"cause":"FDR\u0027s relief programs and appeals to the forgotten man appealed to the needy in 1936.","effect":"He won the 1936 election 523 to 8 and built the New Deal coalition.","why":"Relief recipients, Blacks, urbanites, new immigrants, Southerners, and labor aligned with the Democrats.","difficulty":1},{"id":"d-ce-07","chapter":31,"cause":"The Court struck down or blocked the administration in 7 of 9 major New Deal cases, and FDR won reelection in 1936.","effect":"FDR proposed the court-packing plan in early 1937.","why":"He read his landslide as a mandate and wanted to remove the obstruction of older justices.","difficulty":1},{"id":"d-ce-08","chapter":31,"cause":"Public and congressional outrage met the court-packing plan, and Justice Roberts changed his votes.","effect":"The Court began upholding the Wagner Act and Social Security, and Congress passed only a weak bill for lower courts.","why":"FDR got a friendlier Court but lost goodwill, so few reforms passed after 1937.","difficulty":1},{"id":"d-ce-09","chapter":31,"cause":"New payroll taxes cut incomes and the administration slashed spending to balance the budget in 1937.","effect":"A sharp \u0027Roosevelt recession\u0027 struck, leading FDR to embrace Keynesian deficit spending in April 1937.","why":"The downturn showed that reducing spending too soon undercut weak recovery.","difficulty":1},{"id":"d-ce-10","chapter":31,"cause":"The Tennessee Valley was a poor, eroded region dependent on a power industry accused of overcharging.","effect":"Congress created the TVA to build dams, provide cheap power, and set a rate yardstick.","why":"Public hydroelectric development promised jobs, flood control, and reform of the power monopoly.","difficulty":2}],"frq":[{"id":"a-frq-01","chapter":30,"prompt":"Explain how the automobile transformed American economy and society in the 1920s.","points":["Ford\u0027s assembly line and $5 day cut costs; Model T fell to about two months of wages by 1924","23 million cars by decade\u0027s end; about 6 million jobs in related industries","Installment buying let modest earners buy cars","Suburbs, commuting, paved roads, and changing youth morals","Organized crime used cars for getaways"]},{"id":"a-frq-02","chapter":30,"prompt":"Describe how fear of change and outsiders shaped American responses in the 1920s, using the Red Scare, the Klan, and immigration restriction.","points":["Red Scare 1919-1920: Palmer raids, Buford deportations, criminal syndicalism laws, Sacco and Vanzetti","KKK revived with about 5 million members against Catholics, Jews, Blacks, immigrants, modernity","Immigration Act of 1924 used 2% quotas based on 1890 census and excluded Japanese","Cultural pluralists like Kallen and Bourne opposed the melting pot but were outnumbered"]},{"id":"a-frq-03","chapter":30,"prompt":"Assess the extent of conflict between traditional values and modern culture in the 1920s, discussing Prohibition and the Scopes Trial.","points":["Prohibition (18th Amendment, Volstead Act) backed by churches and women but widely evaded; speakeasies and gangsters like Capone","Scopes Trial 1925: Darrow vs. Bryan; Scopes fined $100; Fundamentalists looked ridiculous but remained strong","Flappers, jazz, Freud, and birth control shocked traditionalists","Writers like Mencken and Fitzgerald challenged conventions; Lost Generation disillusionment"]},{"id":"b-frq-01","chapter":30,"prompt":"Explain TWO ways the Harding and Coolidge administrations favored business in the 1920s.","points":["Mellon\u0027s tax cuts reduced taxes on the wealthy and cut the national debt","Pro-business conservatives staffed courts and agencies, and the Supreme Court struck down progressive laws such as Adkins","Coolidge\u0027s laissez-faire stance and vetoes of farm relief let business have its head","Esch-Cummins Act guaranteed railroad profitability"]},{"id":"b-frq-02","chapter":30,"prompt":"Explain TWO ways US foreign policy in the 1920s reflected a desire for benefits without burdens.","points":["Rejected the League and Versailles, staying out of Europe\u0027s problems","Washington Naval Conference limited ships but provided no enforcement","Kellogg-Briand Pact outlawed war without any means to enforce it","Insisted on war debt repayment while raising tariffs like Fordney-McCumber and Hawley-Smoot"]},{"id":"b-frq-03","chapter":30,"prompt":"Explain TWO causes of the Great Depression and ONE way Hoover responded.","points":["Speculative bubble and credit-fueled boom ended in the 1929 crash","Federal Reserve high interest rates, gold standard, and Hawley-Smoot Tariff deepened the global collapse","Farm and bank failures spread distress","Hoover reluctantly aided banks and railroads and funded public works like Hoover Dam, spending $2.25 billion"]},{"id":"c-frq-01","chapter":30,"prompt":"Evaluate Hoover\u0027s response to the Depression, including the RFC and the Bonus Army episode.","points":["Created RFC in 1932 with $500 million to lend to banks, railroads and local governments, not individuals","Moved beyond 19th-century passivity toward direct federal action","Bonus Army evicted by MacArthur with tear gas in 1932 turned opinion against him","Hoovervilles and the \u0027Hoover depression\u0027 label reflected public anger"]},{"id":"c-frq-02","chapter":30,"prompt":"Explain how the US responded to Japan\u0027s invasion of Manchuria in 1931 and why it failed to stop aggression.","points":["Japan invaded Manchuria in Sept. 1931, closing the Open Door","Stimson Doctrine refused to recognize territory gained by force","US was not in the League and rejected economic pressure","Collective security failed; Japan invaded China fully in 1937"]},{"id":"c-frq-03","chapter":31,"prompt":"Describe Roosevelt\u0027s actions in the Hundred Days and how they addressed relief, recovery and reform.","points":["Bank holiday and Emergency Banking Relief Act restored confidence","Glass-Steagall created FDIC deposit insurance","CCC and FERA provided relief jobs","AAA, NRA and TVA aimed at recovery and reform","Fireside chats and managed currency policy"]},{"id":"d-frq-01","chapter":31,"prompt":"Evaluate the extent to which New Deal programs of 1933-1939 changed the relationship between the federal government and labor.","points":["NRA codes guaranteed collective bargaining, banned yellow-dog contracts, and limited child labor, but were struck down in Schechter Poultry (1935)","Wagner Act (1935) created the NLRB and protected organizing","CIO formed under John L. Lewis, organizing unskilled workers and splitting from the AF of L in 1938","Sit-down strikes at GM Flint won UAW recognition in 1937; violence like the Memorial Day massacre showed resistance","Fair Labor Standards Act (1938) set minimum wages and maximum hours but excluded farm and domestic workers"]},{"id":"d-frq-02","chapter":31,"prompt":"Explain the causes and consequences of FDR\u0027s 1937 court-packing plan.","points":["Court struck down or blocked New Deal measures in 7 of 9 major cases; six justices were over seventy","FDR, after 1936 landslide, proposed adding justices up to fifteen","Critics saw an attack on checks and balances and feared dictatorship","Justice Roberts\u0027s switch led the Court to uphold the Wagner Act and Social Security","Congress passed only a watered-down bill, FDR\u0027s first major legislative defeat; he lost goodwill and later reforms stalled"]},{"id":"d-frq-03","chapter":31,"prompt":"Evaluate the effectiveness of the New Deal in ending the Great Depression, using specific programs and evidence.","points":["Unemployment fell from about 25% in 1933 to about 15% in 1936, but millions remained jobless in 1939","1937 Roosevelt recession followed payroll taxes and budget-cutting; FDR then adopted Keynesian deficit spending","Critics said it was aspirin and Band-Aids; farm surpluses grew; debt rose from $19.5 billion to $40.4 billion","Defenders credited relief, Social Security, FHA, SEC, TVA, and public works for averting collapse and preserving democracy","WWII ultimately ended unemployment"]},{"id":"d-frq-04","chapter":31,"prompt":"Analyze how the New Deal responded to the crisis in agriculture and the Dust Bowl in the 1930s.","points":["AAA paid farmers to reduce acreage to reach parity prices, funded by processing taxes, and was struck down in 1936","Plow-under and pig slaughter angered critics","Dust Bowl caused by drought and mechanized plowing of marginal land; about 350,000 Okies moved to California","Resettlement Administration and CCC windbreaks responded; later farm laws made agriculture heavily subsidized","Indian Reorganization Act and TVA show other rural-oriented efforts"]}]};
